pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #91: Harmonic-Residual Balancing
    // Goal: Minimize post_residual while punishing "fragile" residuals (small remainders that cannot fit future items).

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are too small to fit common items (10-30 range).
    // If a bin has a small remainder, it becomes a "dead" bin.
    if post_residual > 0 && post_residual < 20 {
        score += 45.0 - (post_residual as f64 * 2.25);
    }

    // 2. Lookahead Coupling: If next_item_size is large, favor larger residuals now.
    // If we have a next_item_size and it won't fit in the current post_residual, increase penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Density Normalization: If we have many open bins, prioritize filling them tightly.
    if fitting_bins_count > 0 {
        score += (open_bins_count as f64 * 0.5);
    }

    // 4. New Bin Thresholding: Heavily penalize opening a new bin unless the fit is perfect (0 residual).
    if is_new_bin {
        if post_residual == 0 {
            score = 5.0; // Perfect fit in new bin is acceptable
        } else {
            // Otherwise, make new bin very unattractive unless necessary
            score = 80.0 + (post_residual as f64 * 0.5);
        }
    }

    // 5. Progression adjustment: As the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base score is the residual; we want to minimize wasted space.
    // Penalty for a new bin: if bin_residual == bin_capacity, we are evaluating a new bin.
    // We normalize the penalty based on open_bins_count to prevent excessive bin creation.
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post;

    // Non-linear interaction: Penalize tight fits (very small post_residual) 
    // if the next item is large, as this creates "dead space" that cannot be filled.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if post < next_item && post > 0.0 {
            // Apply a penalty proportional to the mismatch between post and next_item
            score += (next_item - post).powf(1.5) * (1.0 + progress);
        }
    }

    // Heuristic: If we are near the end of the stream (high progress), 
    // be more aggressive about filling existing bins (lower score for smaller post).
    // If we are early, allow slightly more fragmentation to keep options open.
    score += (post / cap) * (1.0 - progress) * 10.0;

    // Apply a massive penalty to opening new bins unless necessary (fitting_bins_count == 0)
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Discourage opening a new bin if we have existing capacity
            score += 50.0 + (mean_residual * 2.0);
        } else {
            // Must open a new bin, neutralize the penalty
            score = 0.0;
        }
    }

    // Bias against fragmentation: penalize bins that deviate significantly from the mean_residual
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals (which are good) 
    // to favor tightest fit, but avoid creating "dead zones" (1-9 range).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead Integration: If next_item_size fits in the post_residual, 
    // heavily reward this bin to favor packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Global State Awareness: If we are late in the stream, prioritize 
    // clearing out bins with low residuals to avoid fragmented endings.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (bin_capacity - bin_residual) as f64 * 0.5;
    }

    // 4. New Bin Thresholding: Discourage opening a new bin unless the 
    // current fit is extremely inefficient (e.g., post_residual is very large).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high.
        score = 85.0;

        // Dynamically lower the cost to open a new bin if we have many bins
        // already open, to prevent excessive fragmentation.
        if open_bins_count > 5 {
            score -= (open_bins_count as f64) * 2.0;
        }
    } else {
        // Penalty for using an existing bin that leaves a "bad" residual space
        // compared to the mean of other open bins.
        if (post_residual as f64) > mean_residual {
            score += 5.0;
        }

        // If this is the only bin that can fit the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: prioritize minimizing post_residual (Best Fit).
    // Apply a non-linear penalty for creating "dead space" (small residuals that are hard to fill later).
    // If post_residual is < 10, it is likely unusable for future items (min size 10), so penalize heavily.
    let dead_space_penalty = if post_residual < 10 && post_residual > 0 { 50.0 / (post + 1.0) } else { 0.0 };

    // Lookahead coupling: If the next item is large, favor bins that leave enough space for it.
    // Penalize placements that leave a residual smaller than the next item if we are mid-stream.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size as f64 - post) * (1.0 - progress)
    } else {
        0.0
    };

    // Global state coupling: Normalize the score based on the mean residual.
    // If this bin is significantly emptier than the average, it's a "wasteful" bin.
    let efficiency_penalty = (bin_capacity - post_residual) as f64 - mean_residual;

    // New bin logic:
    // If bin_residual == bin_capacity, we are evaluating the "Open New Bin" option.
    // Calculate a dynamic threshold for opening a new bin based on progress and fitting availability.
    let mut score = post + dead_space_penalty + lookahead_penalty + (efficiency_penalty * 0.5);

    if bin_residual == bin_capacity {
        // We only open a new bin if the current "best" fit is poor (high score).
        // Bias towards opening new bins later in the stream to consolidate packing.
        score = 45.0 + (progress * 20.0);
    } else if fitting_bins_count == 1 {
        // If this is the only bin that fits the item, make it very attractive.
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;

    // Core metric: Best Fit Decreasing (BFD) logic adjusted by post-placement residual.
    // Lower post_residual is generally better (tighter fit).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: only do it if the best existing fit is extremely poor.
    if is_new_bin {
        // Only open a new bin if the existing bins are highly fragmented or no bins fit.
        // We penalize the new bin based on the mean residual of existing bins.
        score = 25.0 + (mean_residual * 0.5);
    } else {
        // Harmonic-inspired penalty: penalize residuals that are close to useful item ranges (10-80).
        // If the post_residual is small but not zero, it might create "dead space".
        if post_residual > 0 && post_residual < 10 {
