        // Lookahead heuristic: If the next item can fit in the current post_residual, reward this placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }

        // Penalty for using a bin when there are many other options (prevents premature exhaustion of bins).
        score += (open_bins_count as f64) * 0.1;

        // If this is the only bin that fits the item, make it highly attractive to avoid unnecessary new bin usage.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // Progression scaling: As we approach the end of the stream, be more conservative (aggressive packing).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

