    let residual_balance = (post_residual as f64 - (bin_capacity as f64 / 3.0)).abs();
    score += residual_balance * 0.1;

    // Encourage filling existing bins rather than opening new ones, unless the fit is poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy opening cost.
    if bin_residual == bin_capacity {
