        // Dynamically reduce opening cost if we are late in the stream to finish up.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0;
    }

    // If this is the last chance for this item (fitting_bins_count == 1), 
    // prioritize this bin to avoid opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Modulo-based "packing density" bias: favor bins that result in residuals 
    // that are multiples of 10, as they are more likely to be filled by the input distribution.
    if post_residual % 10 != 0 {
