}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Minimize post_residual to keep bins tight.
    // We heavily penalize large post_residuals (dead space).
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic:
    // If post_residual is small, it creates "unusable" gaps.
    // If post_residual is a factor of the capacity, it might be more useful.
    if post_residual > 0 && post_residual < 10 {
