            score -= (bin_capacity - (post_residual - next_item_size)) as f64 * 0.2;
        } else {
            // Penalize placements that make the next item require a new bin
            score += 15.0;
        }
    }

    // 4. Density Balancing:
    // If there are many fitting bins, be more selective.
