        score -= 200.0 * (1.0 + (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // 4. Density Balancing: If we are late in the stream, favor bins with lower mean_residual
    // to consolidate space. If early, allow more fragmentation.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.7 {
