    }

    // 5. New Bin Threshold: If bin_residual == bin_capacity, we are evaluating a new bin.
    // Only open a new bin if the fitting bins are forced to create very poor residuals.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
