    // 4. New Bin Threshold: If evaluating a new bin, penalize it based on total open bins.
    // This forces the algorithm to consolidate items into existing bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
        // Discourage starting a new bin if we are early in the sequence.
        score += (1.0 - (step_index as f64 / total_items as f64)) * 50.0;
    }

    // 5. Residual Balancing: If post_residual is extremely low (a "tight" fit), 
    // reward it, as it minimizes fragmentation.
    if post_residual < 5 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to progress and open bin pressure
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing bin could fit it
            score += 150.0 + (100.0 * progress);
        } else {
            // If no existing bin fits, opening a new bin is mandatory; score it neutrally
            score = 50.0;
