        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }

        // Coupling with global state: penalize creating a bin that deviates from the mean
        // This encourages "clustering" bin fill levels
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.2;

        // Dynamic horizon: as we approach the end, prioritize tightest fit regardless of future
        if progress > 0.8 {
            score -= (100 - post_residual) as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base score: prioritize smaller post_residual (Best Fit)
    // Add a penalty for creating very small gaps that are hard to fill (1-9 range)
    let gap_penalty = if post > 0.0 && post < 10.0 {
        15.0 * (1.0 - post / 10.0)
    } else {
        0.0
    };

    // Interaction term: If we are late in the stream, prioritize aggressive packing (lower residuals)
    // If early, allow slightly higher residuals to keep bins flexible for future large items
    let progress_scaling = 1.0 + (progress * 2.0);

    // Lookahead logic: If the next item is large, penalize bins that cannot accommodate it
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        12.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Fitting constraint: If this is the only bin that fits the item, reward it significantly
    // to avoid opening a new bin unnecessarily.
    let exclusivity_reward = if fitting_bins_count == 1 && res >= item_size as f64 {
        -25.0
    } else {
        0.0
    };

    // New bin handling: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the current open bins are "too full" to be efficient,
    // or if the current bins are so fragmented they can't fit the current item well.
    if res == bin_capacity as f64 {
        // High cost to open a new bin unless existing ones are essentially full or very poorly matched
        50.0 + (mean_residual * 0.5)
    } else {
        (post * progress_scaling) + gap_penalty + lookahead_penalty + exclusivity_reward
    }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We favor bins that result in smaller post_residuals (tighter packing).

    // 2. Harmonic Class Logic:
    // If post_residual is very small (< 10), it might be "dead space" that cannot fit 
    // any future items (since min item size is typically > 10).
    // We add a penalty for "near-empty" gaps that are too small to be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic:
    // If the next item fits in the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Fitting Bin Scarcity:
    // If this is the ONLY bin that can fit the item (fitting_bins_count == 1), 
    // we should prioritize it highly to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 5. New Bin Thresholding:
    // If bin_residual == bin_capacity (New Bin Candidate), we apply a high barrier 
    // to entry to discourage opening new bins unless all existing ones are poor fits.
    if bin_residual == bin_capacity {
        // Only open new if we have many bins open already or the item is large.
        score += 30.0 + (item_size as f64 * 0.5);
    }

    // 6. Harmonic Distribution normalization:
    // Penalize bins that deviate significantly from the mean_residual of open bins.
    // This keeps the "tightness" of bins uniform across the set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
