    }

    // 5. Residual balancing: Penalize placing an item if the resulting residual is significantly 
    // lower than the mean residual of all open bins (preventing "starving" bins).
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead space" that is too small for any likely future item (under 10).
    // If post_residual is tiny (1-9), it is almost always wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead matching: If the next item fits perfectly into the post_residual, 
    // heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // Reward small gaps after the next item is placed
        score -= (100.0 - diff) * 0.5;
    }

    // 3. Prefer bins that keep the mean residual balanced.
    // If this bin's post_residual is significantly lower than the global mean, 
    // it's a tight fit (good).
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // 4. If this is the only bin that fits, we are forced to take it.
    // However, if we are considering a new bin (bin_residual == bin_capacity),
    // increase the cost of opening a new bin if other options exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have alternatives.
            score += 150.0 + (fitting_bins_count as f64 * 10.0);
        } else {
            // Forced to open a new bin.
            score = 0.0;
        }
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // become more aggressive about filling existing bins to reduce total count.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
