    // Dynamic thresholding: as we progress through the stream, 
    // favor filling existing bins over opening new ones (open_bins_count impact).
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales with progress and the number of already open bins.
        // We only open a new bin if the "Best Fit" options are extremely poor.
        score += 40.0 + (progress * 20.0) + (open_bins_count as f64 * 0.5);
    } else {
        // Reward bins that have a residual close to the mean, promoting balanced bin usage.
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // If this is the last fitting bin, slightly reward using it to avoid opening a new bin later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead zones" (1-9)
    // that are unlikely to fit future items. Prefer Best-Fit (min post_residual)
    // while biasing against opening new bins unless the fit is truly optimal.

    let mut score = post_residual as f64;

    // 1. Penalize "dead zones" (1..=9) which are statistically hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. If this bin is the only one that can fit the item, reward it to prevent
    // premature opening of new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 3. Lookahead logic: if next_item_size can fit into the post_residual,
    // make this bin highly attractive.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // 4. Modulo-based "harmonic" alignment: encourage packing items that sum
    // to factors of the capacity (100).
    if (item_size + (bin_capacity - bin_residual)) % 25 == 0 {
        score -= 5.0;
    }

    // 5. New bin penalty: Only open a new bin if the remaining fit quality is poor.
    // If bin_residual == bin_capacity, we are evaluating the cost of a new bin.
    if bin_residual == bin_capacity {
        // Only open new if we have many bins or the current average is already very tight
        score += 12.0; 
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // 6. Global density pressure: as the stream progresses, prioritize closing
    // bins that are nearly full (low post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If post_residual is too small to fit common small items (e.g., < 10),
    // it creates "fragmentation" that is hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual, 
    // reward this placement heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Open bin pressure: If we are choosing between an existing bin and a new bin,
    // penalize opening a new bin unless the existing bins are extremely poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High cost to open a new bin if we have existing bins
        score += (open_bins_count as f64) * 2.5;

        // If we have many open bins, we should prefer filling them rather than opening new ones.
        if open_bins_count > 5 {
            score += 50.0;
        }
    } else {
        // For existing bins, reward bins that maintain a high occupancy (low residual).
        // If the bin is becoming very full, prioritize it to "close" it sooner.
        if post_residual < 15 {
            score -= 15.0;
        }
    }

    // 4. Fitting constraints: If this is the only bin that can fit the item, 
    // prioritize it to avoid forcing a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // 5. Global progression: As we approach the end of the stream, 
    // be more aggressive about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
