    // If the next item is large, we want a bin that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (synergy)
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // If we can't fit the next item, this bin is "blocked" for the next step.
            score += 5.0;
        }
    }

    // 4. Global state adjustment:
    // As the stream nears the end, be more aggressive about filling existing bins
    // to avoid leaving many half-empty bins at the end of the stream.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 5. Balance the number of open bins:
    // If we have many open bins, penalize opening a new one further.
    if open_bins_count > 5 && bin_residual == bin_capacity {
