    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for leaving "dead space": small residuals that are unlikely to fit future items.
    // We penalize residuals in the [1, 9] range heavily as they are mostly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if next_item_size is large, favor larger post_residuals to accommodate it.
    // If next_item_size is 0 (end of stream), prioritize closing bins (lower post_residual).
    if next_item_size > 0 {
        let fit_margin = post_res - next_item_size as f64;
        if fit_margin < 0.0 {
            // Penalize bins that cannot fit the next item
            score += 25.0 * (1.0 - progress);
        } else {
            // Reward bins that create a "perfect" fit for the next item
            score -= 15.0 * (1.0 - (fit_margin / 100.0));
        }
    }

    // Dynamic pressure: as the stream progresses, increase the cost of opening new bins.
    // This is applied when bin_residual == bin_capacity (the "new bin" case).
    if bin_residual == bin_capacity {
        score += 40.0 + (30.0 * progress);
    }

    // Efficiency bias: penalize spreading items across too many bins early on.
    score += (open_bins_count as f64) * 2.0 * (1.0 - progress);

    // Contextual adjustment: if this is the only bin that fits, reduce its score to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
