        score += (open_bins_count as f64 * 5.0) + (mean_residual * 0.5);
    } else {
        // Favor bins that have a high residual (keeping them open for larger future items)
        // vs bins that are already quite full (Best Fit principle)
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Adjust based on fitting_bins_count: if this is the only bin that fits the item, make it highly attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
