        // Penalty is high (e.g., 40.0) initially, tapering off.
        // We only open a new bin if the existing fits are extremely poor (high post_residual).
        score += 40.0 * (1.0 - progress).powf(0.5);
    } else {
        // If it's an existing bin, check if it's the last chance to fit the item.
        if fitting_bins_count == 1 {
            // Strong incentive to use the last available bin rather than opening a new one.
            score -= 20.0;
        }

        // Lookahead heuristic: If the next item is large, favor bins that leave enough space
        // for it, or conversely, bins that are nearly full if the next item is small.
        if next_item_size > 0 {
            let next_item = next_item_size as f64;
            // If the next item fits into the post_residual, reward this bin.
            if post >= next_item {
                score -= 15.0 * (1.0 - (post - next_item) / bin_capacity as f64);
            }
        }
    }

    // Penalize bins that deviate significantly from the mean residual of open bins
    // to encourage bin consolidation (keeping fills consistent).
    let residual_penalty = (post - mean_residual).abs() * 0.1;
    score += residual_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (e.g., residual < 10) that is unlikely to fit future items.
    // We reward bins that leave enough room for common item sizes or the next item.
    if post_residual > 0 && post_residual < 10 {
