    // Lookahead logic: If the next item fits into the post_residual, prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Harmonic class logic: Favor bins that align with the capacity. 
    // If the post_residual is a multiple of 10, it's more likely to fit future items.
    if post_residual % 10 == 0 {
        score -= 10.0;
    }

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless no existing bins can fit the item (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
