        }
    }

    // Dynamic scaling based on progression: As we near the end of the stream, 
    // be more aggressive about packing tightly (penalize large post_residuals).
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress * 0.5;

    // Penalize increasing the number of open bins if we are already using many.
    score += (open_bins_count as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
