    }

    // 5. Global Efficiency: If the post_residual is significantly higher than the current mean_residual,
    // we penalize it to keep open bins "tightly" packed.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
