    // We penalize the existence of a larger residual more heavily as progress increases.
    score += post_res * (progress * 2.0);

    // Lookahead logic: If the next item exists, penalize bins that cannot fit it
    // if the current post_residual is small (creating "dead" space that can't fit upcoming items).
    if next_item_size > 0 {
