        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 15.0; // Reward: leaves room for next item
            } else {
                score += 10.0; // Penalty: lookahead item won't fit here
            }
        }
    }

    // Heuristic: If this is the last fitting bin, prioritize it strongly to avoid unnecessary new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Global state adjustment: If current mean residual is high, prioritize tighter fits
    if mean_residual > 30.0 {
        score += (post_residual as f64) * 0.5;
    }

    // Dynamic scale: heavily penalize creating small "dead" fragments (e.g., 1-5 units)
    if post_residual > 0 && post_residual < 8 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
