    // We define a quadratic penalty for "unusable" gaps (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64).powi(2) * 2.5;
    }

    // Lookahead logic: if the next item is large, favor keeping bins with more space open.
    if next_item_size > 0 {
        let lookahead_penalty = (next_item_size as f64 / (post_residual + 1) as f64).powf(1.5);
        score += lookahead_penalty * 5.0;
    }

    // Dynamic thresholding: as we reach the end of the stream, prioritize closing bins (minimizing open_bins_count).
    // We penalize opening new bins more aggressively as progress increases.
    if is_new_bin {
        score += 15.0 + (progress * 40.0);
    } else {
        // Reward bins that bring the residual closer to the mean_residual of other bins,
        // which helps keep bin fill-levels balanced.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // If this is the last fitting bin, give it a slight priority boost to avoid opening a new bin
    // unless the fit is extremely poor (handled by the quadratic penalty above).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Best-Fit Decreasing (BFD) logic baseline: prioritize smallest post_residual
    let mut score = post_residual as f64;

    // Harmonic/Modulo logic: penalize post_residuals that create "dead zones"
    // Small residuals (1-9) are often unusable (dead space). 
    // We penalize these specifically to force tighter packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: if next_item_size is large, favor bins that can still accommodate it.
    // If post_residual is smaller than next_item_size, we effectively "waste" the capacity for that item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0;
        } else {
            // Reward bins that maintain enough space for the next item
            score -= 15.0;
        }
    }

    // New bin penalty: incentivize using existing bins unless the fit is extremely poor.
    // If bin_residual == bin_capacity, this is a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very low (bins are tight)
        // or if we have no other options.
        if open_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        }
    }

    // Density normalization: as we approach the end of the stream, prioritize 
    // closing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 30.0;
    }

    // Harmonic influence: favor bins where the post_residual is a multiple of 
    // common item sizes (often 20, 25, 33) to leave "clean" space for future items.
    if post_residual % 25 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
