    }

    // 6. Progressive Tightening: As the stream nears completion, become more 
    // aggressive about filling remaining space to avoid trailing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

