    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless no existing bins can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 120.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Prefer opening a new bin if no other options exist
        }
    }

    // 3. Lookahead Synergy: Reward placements that leave room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit reward
            if post_residual == next_item_size {
                score -= 30.0;
            } else {
                score -= 15.0;
            }
        }
    }

    // 4. Density Balancing: Favor bins with lower residuals (Best Fit behavior)
    // weighted by the progression of the stream.
    let progress = step_index as f64 / total_items as f64;
    score += (bin_capacity - bin_residual) as f64 * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best-Fit (minimize post_residual)
    // We prioritize bins that create the smallest gap.

    // 2. Lookahead Penalty/Reward:
    // If the post_residual is less than the next item, we create an orphan space.
    // If it is exactly equal or slightly more than the next item, we reward it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a hole that cannot fit the next item
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if post_residual == next_item_size {
