    // 3. Global Efficiency:
    // If we are late in the stream, be more aggressive about filling existing bins
    // to avoid leaving fragmented space at the end.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // 4. Fitting Constraint:
    // If this is the only bin that fits, we should prioritize it heavily
    // unless the post_residual is extremely poor.
    if fitting_bins_count == 1 && post_residual < 20 {
        score -= 40.0;
    }

    // 5. New Bin Logic:
    // Only open a new bin if the current best existing bin is "very bad" (residual > 40)
    // and we have plenty of open bins already.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && post_residual > 40 {
            score = 30.0; // Moderate cost to open a new bin
        } else {
            score = 100.0; // High cost to open a new bin prematurely
        }
    }

    // 6. Mean Residual Balancing:
    // Avoid bins that deviate too far from the average residual to maintain uniformity.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
