        // Only open a new bin if the average residual is already quite low (bins are full).
        // Otherwise, force the item into existing bins.
        score += 80.0 + (mean_residual * 2.0);
    }

    // 6. Progression scaling: As we approach the end of the stream, be more conservative.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual values that are too small to fit typical items (10-20)
    // but large enough to waste capacity. If post_residual is in (0, 10), it's high-risk.
    if post_residual > 0 && post_residual < 10 {
