pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Strategy: Prefer bins that leave minimal residual space (Best Fit),
    // but penalize bins that leave "fragile" residuals (small gaps that are hard to fill).

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base cost: The tighter the fit, the lower the score (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalty for creating unusable gaps (dead space between 1 and 9).
    // If post_residual is small but > 0, it's often a "dead" zone.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
