    if is_new_bin {
        score += 15.0 + (open_bins_count as f64 * 0.5);
        // Late-stage: Be more aggressive about starting new bins to finish the pack.
        score -= 20.0 * progress;
    }

    // 5. Fitting Context: If this is the only bin that fits the current item, 
    // discourage using it if the post_residual is very high (wasteful).
    if fitting_bins_count == 1 && !is_new_bin {
        if post_residual > 50 {
            score += 30.0;
        }
    }

    // 6. Mean Residual Balancing: Avoid bins that deviate significantly from the mean 
