pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger residuals (Best Fit logic)
    let mut score = post;

    // Non-linear coupling: penalize small residuals that are too small to fit common upcoming items
    // If post_residual is < next_item_size, we create a "dead zone". 
    // We increase score (penalize) as we approach the end of the stream.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * (1.0 + progress * 2.0);
    }

    // Dynamic thresholding: If we have many bins open, prioritize filling the tightest one (lowest post)
    // If we have few bins, be more permissive to keep options open.
    score += (open_bins_count as f64 * 0.5) * (post / bin_capacity as f64);

    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many 
    // other bins could have taken the item. Only open a new bin if the fit is truly poor elsewhere.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales with progress to encourage packing density earlier
        // but allows opening new bins if fitting_bins_count is low.
        score += 25.0 + (progress * 15.0) - (fitting_bins_count as f64 * 5.0);
    } else {
        // Reward bins that bring the mean residual closer to a "perfect" packing density (usually ~10-15%)
        let deviation = (post - (bin_capacity as f64 * 0.12)).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
