    // The base score is already post_residual. We refine this by penalizing 
    // "orphaned" small residuals that are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // Heavy penalty for creating slivers that are hard to fill
    }

    // 2. Lookahead Integration: 
    // If the next item is large, avoid leaving a residual that is slightly smaller than it.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // 3. Global State Balancing:
    // If we have many open bins, prioritize closing them (Best-Fit).
    // If we have few open bins, prioritize preserving space for future items.
    score += (open_bins_count as f64 * 2.0) * (1.0 - progress);

    // 4. New Bin Logic:
    // Only open a new bin if the current fit is extremely poor (large residual).
    // We normalize the decision to open a new bin based on the average state.
    if bin_residual == bin_capacity {
        // High penalty to open new bins unless we are forced or the mean residual is very high.
        score = 60.0 + (mean_residual * 0.5);
    } else {
        // If it's the last chance (only one bin fits), prioritize this bin heavily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Reward bins that keep the residual close to the global mean (stability).
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space after placement. 
    // We want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for leaving "dead space": 
    // If post_residual is small but > 0, it becomes unusable for larger items.
    // We penalize values of post_residual that are too small to fit common items 
    // but large enough to waste capacity.
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - post / 10.0);
    }

    // Lookahead coupling: If the next item is large, we want to preserve 
    // space in bins that can accommodate it.
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        score += 0.5 * diff;
    }

    // Dynamic thresholding based on stream progress:
    // As the stream progresses, we become more conservative about opening new bins.
    // If this is a new bin (bin_residual == bin_capacity), we penalize it 
    // more heavily as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 15.0 + (30.0 * progress);

        // If there are other bins that could fit this, penalize opening a new one significantly.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Interaction with mean_residual:
    // If the mean residual of current bins is high, we are being inefficient.
    // Penalize placements that increase the mean residual further.
    score += (mean_residual - post) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
