            score += 10.0;
        }
    }

    // 5. Modulo-based Efficiency: Favor placements that leave residuals 
    // which are multiples of 10 or 20, as these align with potential item size distributions.
    let remainder = post_residual % 10;
    if remainder == 0 {
        score -= 5.0;
    } else if remainder > 7 {
        score += 5.0;
