    // 2. Harmonic Class Logic: Reward residuals that are perfect multiples of common item sizes
    // This encourages "tight" fits that leave space for future items.
    if post_residual > 0 && post_residual % 20 == 0 {
        score -= 15.0;
    }

    // 3. Lookahead Optimization: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. Fitting Constraint: If this is the only fitting bin, reward it to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // 5. Global Balance: Penalize opening new bins unless the current bins are very full.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            // New bin is wasteful if existing bins have significant space.
            score += 60.0;
        } else {
            // New bin is acceptable if existing space is fragmented.
            score += 10.0;
        }
    }

    // 6. Progress Scaling: As the stream nears completion, become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

