}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (already in 'score')
    // 2. Harmonic Penalty: Penalize gaps that are unusable for common item sizes (e.g., < 10)
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    }

    // 3. Lookahead logic: If a future item fits perfectly into the residual, prioritize this bin
    if next_item_size > 0 {
