    // 4. Thresholding: Avoid opening new bins unless necessary
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if existing bins can take the item
            score += 85.0 + (open_bins_count as f64 * 2.0);
