    // 5. Density heuristic: If the bin is becoming very sparse compared to the mean, 
    // prioritize filling it to keep the mean residual low across all bins.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 6. Harmonic Class Bias: Prefer bins that leave room for a "complementary" item
    // Logic: 100 / (100 - post_residual) creates a preference for specific fractional fills
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
