        }
        // If the current item fits perfectly, reward it.
        if post_residual == 0 {
            score -= 5.0;
        }
    }

    // Global state awareness:
    // If we have many bins open, try to consolidate by penalizing new bins more heavily
    // and rewarding bins that are already closer to the mean density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // Last chance logic:
    // If this is the only bin that can fit the item, we are forced to take it.
    // However, if we are considering a new bin when fitting_bins_count > 0, penalize the new bin.
    if is_new_bin && fitting_bins_count > 0 {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
