    // Penalize new bins heavily early on, but less so as the stream progresses.
    let mut score = post_residual as f64;

    // Penalty for creating a new bin:
    // If we have other options (fitting_bins_count > 0), we make opening a new bin expensive.
    if is_new_bin {
