            score += 15.0;
        }
    }

    // Balance open bins: If many bins are open, favor filling the ones with 
    // the least residual to keep the average residual high for larger items.
    let residual_penalty = (bin_residual as f64 - mean_residual).abs() * 0.1;
    score += residual_penalty;

    // Favor bins that are already partially full to consolidate space.
    if !is_new_bin {
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
