            score += 10.0;
        }
    }

    // 3. Global state adaptation: 
    // If fitting_bins_count is 1, this is the only bin that can take the current item.
    // If it's a new bin (residual == capacity), we only want to open it if we must.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can accommodate the item
            score += 60.0 + (open_bins_count as f64 * 0.5);
        }
    } else {
        // Encourage filling bins that are already below the mean_residual to keep them compact
        if post_residual < mean_residual as u32 {
            score -= 5.0;
        }
    }

    // 4. Progress-based scaling: Be more aggressive in filling bins as the stream nears completion
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Decreasing logic: We want the smallest post_residual (tightest fit).
    // Penalize large post_residuals exponentially to avoid fragmentation.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead optimization: If the next item fits into the current post_residual,
    // strongly prefer this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Global state: If we are near the end of the stream, prioritize closing bins
    // to reduce total_bins_used, even if it creates slightly larger residuals.
    if progress > 0.95 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. New bin penalty: If this is an empty bin, add a heavy "opening cost"
    // to discourage starting new bins unless the current options are truly poor.
    if bin_residual == bin_capacity {
        score += 45.0 + (mean_residual * 0.5);
    }

    // 5. Scarcity adjustment: If this is the only bin that can fit the item,
    // be careful not to make it too "attractive" if it leaves a very awkward
    // residual (e.g., 1-9 space), which is hard to fill later.
    if fitting_bins_count == 1 && post_residual < 10 {
        score += 20.0;
    }

    // 6. Balance: Penalize bins that deviate too far from the mean residual
    // to encourage uniform bin filling.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

