    let mut score = post.powf(1.5);

    // Penalty for creating "dead zones": if the post_residual is too small to fit 
    // likely future items (e.g., < 10), it is often better to use a different bin.
    if post > 0.0 && post < 15.0 {
        score += 50.0 * (1.0 - post / 15.0);
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // reward this bin heavily to encourage pairing.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 40.0 * (1.0 + progress);
    }

    // New bin aversion: penalize opening a new bin (where bin_residual == bin_capacity)
    // as the stream progresses, unless no other bin can fit the item.
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // Balance open bins: if we have many open bins, penalize opening another one
    // by scaling the score relative to the mean residual of existing bins.
    if open_bins_count > 0 {
        let residual_diff = (post - mean_residual).abs();
        score += residual_diff * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize based on the progress of the stream.
    // Opening a new bin early is expensive; opening it late is necessary.
    if bin_residual == bin_capacity {
        score += 100.0 * (1.0 - (step_index as f64 / total_items as f64));
    }

    // 2. Harmonic/Modulo logic: Favor post_residuals that are multiples of 
    // common item sizes or leave "clean" space.
    let remainder_mod = (post_residual % 10) as f64;
    score += remainder_mod * 0.5;

    // 3. Lookahead integration: If next_item_size is large, avoid leaving 
    // a post_residual that is just slightly too small to fit it.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual >= (next_item_size / 2) {
            // This is a "dead zone" for the next item. Penalize heavily.
            score += 45.0;
        } else if post_residual >= next_item_size {
            // Ideal: The bin can accommodate the next item. Reward it.
            score -= 20.0;
        }
    }

    // 4. Density Balancing: If we have many open bins, penalize creating 
    // a new one or leaving a bin very empty.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += (open_bins_count as f64) * 5.0;
    }

    // 5. Fitting constraint: If this is the only bin that fits the current item, 
    // heavily prioritize it to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Efficiency bias: Penalize creating bins with high fragmentation 
    // compared to the current mean_residual.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
