    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 2.0;
    }

    // 4. New Bin Thresholding: If this is a new bin (residual == capacity),
    // assign a baseline cost that discourages opening new bins unless the
