    // 2. Penalty for wasting space that could have fit the lookahead item
    if next_item_size > 0 && post_residual < next_item_size {
        // Punish bins that become "dead" for the next item
        score += 50.0;
    }

    // 3. Harmonic approach: prioritize bins that leave a residual which is a multiple of common item sizes
    // This reduces fragmentation by creating "clean" remaining capacities.
    let remainder_mod = (post_residual % 20) as f64;
    score += remainder_mod * 0.5;

    // 4. Threshold logic: if we have few fitting bins, prioritize filling the tightest one
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // 5. Global state normalization:
    // If we are at the end of the stream, prioritize filling existing bins aggressively
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    // 6. Penalty for opening new bins:
    // If bin_residual == bin_capacity, this is a candidate for a new bin.
    // We add a high cost to open a new bin unless the current mean_residual is very low (fragmentation).
    if bin_residual == bin_capacity {
        score += 35.0 + (mean_residual * 0.2);
    }

    // 7. Balance against mean_residual:
    // If the bin is much fuller than the average, it's a good candidate (lower score).
    if (bin_capacity - bin_residual) as f64 > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize gaps that are too small to fit future items.
    // If post_residual is in (0, 10), it is likely "dead space" because min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins when existing ones are available.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for opening a new bin if we have plenty of open bins already.
        score += (open_bins_count as f64) * 5.0;
        // If there is another bin that could fit this item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Reward filling existing bins that are close to the mean_residual to keep pack density uniform.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // 4. End-of-stream optimization: Force tighter packing as total_items approaches.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score is the post-placement residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin prematurely unless we are forced to.
    // If bin_residual == bin_capacity, this is the "new bin" candidate.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other bins can fit the item.
            score += 1000.0;
        } else {
            // If no other bin fits, this is neutral.
            score = 0.0;
        }
    }

    // 2. Lookahead matching: Reward placements where post_residual fits the next_item_size.
    // If the next item fits perfectly in the remaining space, we prioritize this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact fits for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= (100.0 - gap) * 0.5;
        } else {
            // Penalize creating a "dead" gap that is too small for the next item.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // 3. Pressure management: If current bin residual is far from the mean,
    // penalize creating even smaller residuals (to keep bins balanced).
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 20.0;
    }

    // 4. Progress-based refinement: In the late stages, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        // Late game: favor filling existing bins aggressively to reduce total count.
        score -= (open_bins_count as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is too small for common future items
    // If post_residual is small but not zero, it's often a "dead zone"
    if post_residual > 0 && post_residual < 15 {
        score += 45.0;
    }

    // Heuristic: Best-Fit Decreasing logic modified by dynamic lookahead
    // If we have a next item, prioritize keeping space for it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    }

    // Penalty for opening new bins when space is available
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Only open a new bin if the mean residual is already quite low (tight packing)
            // or if we are late in the sequence to avoid stragglers
            score += 35.0 + (mean_residual * 0.5) + (progress * 15.0);
        }
    } else {
        // If this bin is the only one that fits, give it a significant bonus
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Reward filling bins to levels that are multiples of common item sizes (e.g., 20, 25, 50)
        let fill_level = bin_capacity - post_residual;
        if fill_level % 25 == 0 {
            score -= 10.0;
        }
    }

    // Dynamic horizon: As we approach the end of the stream, prioritize packing tighter
    // to minimize the number of open bins left over.
    score += (1.0 - progress) * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (lower post_residual).
    // Penalize empty bin creation early in the stream to force densification.
    let mut score = post_res;

    // Penalty for creating a new bin:
    // If this is a new bin (bin_residual == bin_capacity), apply a dynamic threshold.
    // As the stream progresses, the penalty for opening a new bin decreases slightly 
    // to allow for better packing configurations towards the end of the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + (20.0 * (1.0 - progress));
    } else {
        // For existing bins, penalize configurations that leave "dead space" 
        // that is smaller than the smallest likely future items (e.g., < 10).
        // Coupling the post_residual with the mean_residual to favor bins 
        // that align with the global state.
        if post_res < 10.0 && post_res > 0.0 {
            score += 15.0 * (1.0 - (post_res / 10.0));
        }

        // Lookahead coupling: If a known next_item_size cannot fit in the 
        // resulting post_residual, apply a non-linear penalty.
        if next_item_size > 0 && post_res < next_item_size as f64 {
            score += 12.0 * (1.0 - (post_res / next_item_size as f64));
        }
    }

    // Encourage filling bins that are already "closer" to the mean residual 
    // to keep the distribution of bin usage uniform.
    let deviation = (post_res - mean_residual).abs();
    score += 0.5 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. If this is a new bin, penalize based on the current average efficiency
    // to prevent opening new bins unless the existing ones are very poorly packed.
    if bin_residual == bin_capacity {
        score += 25.0 + (mean_residual * 0.5);
    } else {
        // 2. Best-Fit Decreasing logic: reward smaller post_residuals (tighter fits).
        // Heavily penalize "fragmentation" (post_residual < 10) if the next item is large.
        if post_residual < 10 && next_item_size > 20 {
            score += 40.0;
        }

        // 3. Lookahead synergy: If the next item can fit in the remaining space,
        // reward this bin to keep the next item "housed" in an existing bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }

        // 4. Harmonic penalty: penalize residuals that are non-multiples of standard 
        // item sizes, favoring "clean" bin states.
        if post_residual % 10 != 0 {
            score += 5.0;
        }

        // 5. If this is the only bin that can fit the item, prioritize it to avoid
        // forced new-bin creation (fitting_bins_count == 1).
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 6. Dynamic pressure: as the stream nears the end, become more conservative
    // about opening new bins by increasing the penalty for new bin creation.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (e.g., < 10), it often creates 
    // "unusable" space that cannot fit typical items (10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual, 
