    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // 5. Global Efficiency: Penalize high mean_residual to encourage filling bins tightly
    // relative to the stream progression.
    score += mean_residual * (step_index as f64 / total_items as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post-residuals to favor tight fits.
    // We add a cubic term to severely punish large gaps.
    score += (post_residual as f64).powi(3) / 100.0;

    // 2. Lookahead Matching: Reward placements where the remaining space 
    // can accommodate the next item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: significantly lower the score if it fits the next item.
            score -= 250.0;
        } else {
            // Penalty: if it creates a gap too small for the next item, 
            // but the gap is large enough to be 'wasted' space.
            score += (100.0 - post_residual as f64) * 0.5;
        }
    }

    // 3. Last-Chance Logic: If this is the only bin that fits the current item, 
    // we prioritize it highly to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // 4. New Bin Thresholding: If evaluating a brand new bin (bin_residual == bin_capacity),
    // apply a heavy penalty unless the current open bins are extremely inefficient.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already very tight.
        // This forces the algorithm to exhaust existing bins first.
        score += 150.0 + (mean_residual * 2.0);
    }

    // 5. Global Efficiency: Slowly increase preference for tighter packing as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Current progress factor (0.0 to 1.0)
    let progress = step_index as f64 / total_items as f64;

