    let mut score = post_residual as f64;

    // Penalty for opening a new bin: discourage unless the fit is extremely poor
    if bin_residual == bin_capacity {
        // Only open a new bin if we are early in the process or if current open bins are very crowded
        // Threshold increases as we progress to favor filling existing bins late-game
        score += 25.0 * (1.0 - progress) + (mean_residual * 0.5);
    } else {
        // Reward placements that leave a residual space suitable for the next item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
