            } else if post_residual > 0 {
                score += 10.0; // Penalty for stranding small unusable space
            }
        }

        // Discourage "fragmenting" by penalizing residuals that are too small to fit common items (e.g., < 10)
        if post_residual > 0 && post_residual < 10 {
