}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the square of the post_residual to heavily penalize large gaps (Best Fit principle).
    let mut score = post * post;

    // Penalty for creating a "fragmented" bin (a bin with a small, unusable residual).
    // If post_residual is small (e.g., < 10), it is likely to remain empty.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 200.0 * (next_item_size as f64 / post);
    }

    // Dynamic thresholding: As the stream progresses, become more conservative about opening new bins.
    // If bin_residual == bin_capacity, we are evaluating a brand new bin.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early, decreasing as the stream nears the end.
        let new_bin_penalty = 1500.0 * (1.0 - (0.5 * progress));
        score += new_bin_penalty;
    } else {
        // Reward bins that have residuals close to the mean, promoting balanced packing.
        let deviation = (post - mean_residual).abs();
        score += 50.0 * deviation / (bin_capacity as f64);

        // Penalize the "last resort" bin if it results in a very poor fit.
        if fitting_bins_count == 1 {
            score -= 100.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

