        score += 20.0 + (open_bins_count as f64 * 5.0) * (1.0 - progress);
    }

    // 6. Mean Residual Balancing:
    // If this bin's post_residual is significantly lower than the mean, it's a tight fit.
    if (post_residual as f64) < mean_residual {
