    // If post_residual is smaller than the next item, we penalize the current choice to prevent blocking.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // 3. Efficiency coupling: Avoid creating bins with very small residuals (the "dead space" problem).
    // We penalize post_residuals that are too small (e.g., < 10) unless it's a perfect fit (0).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // 4. Global balance: If fitting_bins_count is low, we are running out of options for this item.
    // Reward bins that keep the bin count low when the stream is near completion.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 5.0 * progress;
    }

    // 5. Non-linear interaction: Penalize bins that deviate significantly from the mean_residual.
    // This promotes uniform packing density across all active bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We heavily penalize residuals between 1 and 9 (the smallest item size is often 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: if the next item fits into the post_residual, reward this bin placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Harmonic Class logic: favor placements that leave a residual which is a multiple of 10,
    // as these are more likely to accommodate common item sizes (10, 20, 25, 50).
    if post_residual % 10 == 0 {
        score -= 10.0;
    }

    // If this is the last chance to fit the item in an existing bin, prioritize it strongly
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Heuristic for new bin: only open a new bin if the current post_residual is "bad"
    // (i.e., creates a large amount of unusable space).
    if bin_residual == bin_capacity {
        // Higher base cost for new bins, but reduced if the item is very large.
        score = 60.0 + (item_size as f64 * 0.2);
    }

    // Influence of open bins: penalize opening too many bins as the stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
