    // 2. Penalize opening new bins unless the fit is extremely poor or we are near the end.
    // 3. Use lookahead to avoid creating "dead space" that cannot fit the next item.

    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    if is_new_bin {
        // Only open a new bin if we have no other options, or if existing bins are too tight for the next item.
        if fitting_bins_count > 0 {
            score += 45.0 + (progress * 20.0);
        } else {
            score -= 10.0;
        }
    } else {
        // Penalize bins that leave very small gaps (e.g., < 10) unless it's a perfect fit.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // Lookahead: If the current placement makes it impossible to fit the next item 
