        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0;
        }

        // Global state: If the current bin's residual is significantly lower than the mean,
        // it is a "tight" bin. We prefer filling tight bins to keep open bins consolidated.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Dynamic horizon: As we reach the end of the stream, prioritize closing bins
    // by preferring tighter fits.
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

