}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let cap = bin_capacity as f64;

    // Base score: punish large post-residuals (Best Fit strategy)
    // We want to minimize post_residual, but prioritize tight fits.
    let mut score = post * post / cap;

    // Interaction term: penalize opening new bins early in the stream
    // but allow it if the current fit leaves a "dead zone" (1-9 space)
    if res == cap {
        // Penalty for opening a new bin is scaled by progress
        // As we reach the end of the stream, opening a new bin becomes less penalized
        score += (cap - item_size as f64) * (1.5 - progress);
    } else {
        // Reward fits that leave very little space (0-5)
        if post < 6.0 {
            score -= (6.0 - post) * 10.0;
        }

        // Lookahead bias: if the next item is large, favor bins that can accommodate it
        if next_item_size > 0 && next_item_size > post_residual {
            score += (next_item_size as f64 - post) * 0.5;
        }
