    // Penalize creating bins with residuals that are unlikely to fit future items
    // based on the mean_residual of current open bins.
    let dev = (post - mean_residual).abs();
    score += dev * 0.1;

    // Final scaling: favor bins that are already partially full to consolidate space
    let fill_ratio = (cap - res) / cap;
    score -= fill_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
