    // As we approach the end of the stream, penalize opening new bins more aggressively
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    // 4. Fitting constraints: avoid creating "orphaned" bins
    // If this is the last bin that can fit the item, prioritize it to save space
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // 5. Mean residual equilibrium: avoid creating bins that deviate significantly from the mean
    // This helps keep bin fills consistent
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * deviation;

    // 6. Threshold for new bin creation:
    // Only open a new bin if the post_residual is "too good" (i.e., we are wasting a perfectly good bin)
    // or if the current bin's remaining space is essentially useless (e.g., < 10)
    if bin_residual == bin_capacity && post_residual > 50 {
        score -= 10.0; // Moderate incentive to start a fresh bin if space is abundant
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post-placement residual. 
    // We want to minimize this (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating 'dead space' (small residuals that are unlikely to fit future items).
    // If post_residual is < 10, it's likely wasted. We penalize this exponentially.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_res).powi(3);
    }

    // Lookahead logic: If the next item cannot fit into this post_residual, 
    // we penalize the current placement slightly to favor bins that leave room for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Dynamic thresholding based on stream progress:
    // Early in the stream, we are more conservative about opening new bins.
    // Late in the stream, we prioritize closing bins (minimizing residuals) over opening new ones.
    let fill_ratio = 1.0 - (post_res / bin_capacity as f64);
    score -= fill_ratio * 5.0 * (1.0 - progress);

    // If this is a new bin (bin_residual == bin_capacity), we penalize it 
    // heavily unless we are forced to open it or the fit is exceptionally good.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the current fit quality is poor across all open bins.
        // We add a cost that decreases as the stream progresses, making it easier to open
        // new bins near the end of the stream if necessary.
        score += 45.0 * (1.0 - (progress * 0.5));
    } else {
        // Reward bins that keep the mean residual balanced.
        // If this bin's post_residual is significantly lower than the mean, 
        // it's a good candidate (it's "tighter" than average).
        if post_res < mean_residual {
            score -= (mean_residual - post_res) * 0.8;
        }
    }

    // Final adjustment: penalize leaving too many bins open if we are near the end.
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We target residuals that are either 0 (perfect fit) or >= next_item_size.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 50.0 + (next_item_size - post_residual) as f64 * 2.0;
        } else if post_residual < 15 {
