    // Harmonic preference: Reward bin usage that keeps the mean residual closer to 
    // the capacity/2 mark to maintain flexibility for future item sizes.
    let residual_balance = (post_residual as f64 - (bin_capacity as f64 / 3.0)).abs();
    score += residual_balance * 0.1;

    // Encourage filling existing bins rather than opening new ones, unless the fit is poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy opening cost.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Dynamically reduce opening cost if we are late in the stream to finish up.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0;
    }

    // If this is the last chance for this item (fitting_bins_count == 1), 
    // prioritize this bin to avoid opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Modulo-based "packing density" bias: favor bins that result in residuals 
    // that are multiples of 10, as they are more likely to be filled by the input distribution.
    if post_residual % 10 != 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
