        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "sliver" residuals
    // that are too small for common items, while rewarding fits that leave space
    // for the lookahead item.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "dead space": residuals below 10 are often unusable.
    // If we create a small residual, we add a penalty to discourage it.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead matching: If the next item fits into the post_residual, 
    // significantly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if this makes the bin almost perfectly full
        if post_residual - next_item_size < 5 {
            score -= 20.0;
        }
    }

    // 3. Pressure management: If we are running out of space in the bin, 
    // we want to avoid creating many bins with very low residuals.
    // We penalize bins that deviate significantly from the mean_residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 4. New bin threshold: If this is a new bin (bin_residual == bin_capacity),
    // only pick it if we cannot find a good fit in existing bins.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current fitting options are poor (e.g., they all result in small slivers)
        // or if we are very early in the stream.
        score += 30.0; 

        // If there are no other fitting bins, we are forced to open a new one.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // 5. Final constraint: If this is the last chance to fit an item into an existing bin,
    // give it a slight priority boost to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // 2. Dead-Space Penalty: If post_residual is small but > 0, it's often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 3. Lookahead Strategy: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize bin density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Global State: If we have many open bins, prioritize filling existing ones.
    // If we are nearing the end of the stream, be more aggressive with consolidation.
    if fitting_bins_count > 0 {
        // Penalty for opening a new bin when existing ones exist
        if bin_residual == bin_capacity {
            score += 60.0 * (1.0 - progress);
        }
    }

    // 5. Dynamic Thresholding: Adjust based on mean_residual to avoid fragmented bins.
    // If the current bin is emptier than the mean, prefer filling it.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 6. Final constraint: Favor small post_residual to pack tightly, 
    // but avoid creating "unfillable" gaps (1-9 range).
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the post_residual (Best Fit logic)
    let mut score = post_res;

    // Penalty for creating a "fragment" (small, unusable space)
    // We penalize post_residual values that are too small to fit typical future items (e.g., < 10)
    if post_res > 0.0 && post_res < 10.0 {
        score += 20.0 * (1.0 + progress);
    }

    // Encourage packing into bins that are already "half-full" to keep future options open
    // We adjust score based on the deviation from the mean_residual
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * deviation * progress;

    // Lookahead: if next_item_size is large, penalize small post_residual to avoid blocking
    if next_item_size > 50 {
        if post_res < next_item_size as f64 {
            score += 30.0 * (1.0 - progress);
        }
    }

    // Discourage opening a new bin (bin_residual == bin_capacity) unless necessary
    if bin_residual == bin_capacity {
        // Only open new if fitting_bins_count is low or current progress suggests efficiency
        score += 15.0 + (25.0 * (1.0 - progress));
    }

    // Prioritize bins that have exactly enough space (Perfect Fit)
    if post_res == 0.0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating small, unusable gaps (The "Dead-Zone" penalty).
    // Gaps between 1 and 9 are extremely difficult to fill given the input constraints.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Harmonic Lookahead: Check if next_item_size fits in the remaining space.
    // If next_item_size fits perfectly into the post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap_after_next = post_residual - next_item_size;
            // Reward fits that leave a multiple of 10 or 20 (harmonic alignment)
            if gap_after_next == 0 {
                score -= 40.0;
            } else if gap_after_next % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // Penalty if we block a potential future fit
            score += 15.0;
        }
    }

    // 3. Pressure management: If fitting_bins_count is low, we are constrained.
    // Prioritize tighter fits as we run out of options.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // 4. Distributional balance: Penalize deviating significantly from the mean_residual
    // of other bins to prevent "bin fragmentation" (some very full, some very empty).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. New-bin thresholding: Ensure we only open a new bin if the fit is truly bad.
    if bin_residual == bin_capacity {
        // Only consider a new bin if the average residual is already high 
        // or if we have very few open bins (early game).
        if open_bins_count > 0 && mean_residual < 30.0 {
            score += 45.0;
        } else {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (too small to fit common items), 
    // it creates "fragmentation." We penalize residuals in the [1, 9] range heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, 
    // reward this bin to keep the bin tightly packed.
    if next_item_size > 0 && post_residual >= next_item_size {
