    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is perfect (Best Fit).
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty based on 
    // how many bins are already open to force consolidation.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. Last Chance Heuristic: If this is the only bin that can fit the item,
    // strongly favor it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Efficiency: If the current post_residual is significantly lower 
    // than the global mean_residual, it is a "tight" bin. Reward it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a 'dead zone' that is too small for future items
    // If the post_residual is smaller than the next item, we penalize it heavily.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // Reward bins that bring the post_residual close to the mean_residual of open bins
    // This encourages uniformity in bin exhaustion.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // Penalty for opening a new bin if we have other options.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 55.0; // High barrier to open new bin
    }

    // Heuristic: If this is the last chance to fit an item in an existing bin, 
    // prioritize it to avoid fragmenting the bin space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Dynamic scale based on progression: as we reach the end of the stream, 
    // be more aggressive about filling bins (Best Fit Decreasing logic).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (bin_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (wasted space)
    // We favor smaller post_residuals (tighter fits).

    // 2. Lookahead Coupling: If next_item_size is large, avoid leaving a small residual.
    // If the next item cannot fit in the current post_residual, we penalize this bin.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that leave exactly enough space for the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already (to avoid fragmentation)
        // or if the item fits poorly in all existing bins.
        score += (open_bins_count as f64) * 2.5;
        score -= (mean_residual * 0.8);
    }

    // 4. Scarcity Logic:
    // If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Global State Balancing:
    // As the stream progresses, prioritize closing bins (lower mean_residual)
    let progress = step_index as f64 / total_items as f64;
    score += (mean_residual * progress * 2.0);

    // 6. Fragmentation Penalty:
    // Discourage creating bins with residuals that are very hard to fill (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base score is the residual; we want to minimize wasted space.
    // Penalty for a new bin: if bin_residual == bin_capacity, we are evaluating a new bin.
    // We normalize the penalty based on open_bins_count to prevent excessive bin creation.
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post;

    // Non-linear interaction: Penalize tight fits (very small post_residual) 
    // if the next item is large, as this creates "dead space" that cannot be filled.
    if next_item_size > 0 {
        let next_item = next_item_size as f64;
        if post < next_item && post > 0.0 {
            // Apply a penalty proportional to the mismatch between post and next_item
            score += (next_item - post).powf(1.5) * (1.0 + progress);
        }
    }

    // Heuristic: If we are near the end of the stream (high progress), 
    // be more aggressive about filling existing bins (lower score for smaller post).
    // If we are early, allow slightly more fragmentation to keep options open.
    score += (post / cap) * (1.0 - progress) * 10.0;

    // Apply a massive penalty to opening new bins unless necessary (fitting_bins_count == 0)
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Discourage opening a new bin if we have existing capacity
            score += 50.0 + (mean_residual * 2.0);
        } else {
            // Must open a new bin, neutralize the penalty
            score = 0.0;
        }
    }

    // Bias against fragmentation: penalize bins that deviate significantly from the mean_residual
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

