    // as they create "dead space" that cannot fit typical items (10-80).
    // Specifically, if post_residual < 10, it's highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
