    // We want to force consolidation when the stream is nearly exhausted.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 
        25.0 + (progress * 50.0) 
    } else { 
        0.0 
    };

    // Best-Fit Decreasing logic: favor bins that leave the least space (lower post_residual).
    // Square the post_residual to heavily penalize "wasted" large gaps.
    let base_score = post * post / 100.0;

    // Lookahead interaction: if the next item is large, avoid leaving a residual that is too small for it.
    // If post_residual < next_item_size, we create a 'stranded' gap.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        (next_item_size as f64 - post) * 1.5
    } else {
        0.0
    };

    // Use mean_residual to balance the load. If this bin's post_residual is significantly 
    // higher than the average, it is a poor placement (fragmentation risk).
    let fragmentation_penalty = if post > mean_residual {
        (post - mean_residual) * 0.5
    } else {
        0.0
    };

    // If this is the only bin that fits the item, make it highly attractive to avoid opening a new one.
    let urgency_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -40.0
    } else {
        0.0
    };

    base_score + new_bin_penalty + lookahead_penalty + fragmentation_penalty + urgency_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
