    // 4. Mean Residual Coupling: Penalize bins that deviate significantly from the 
    // current mean residual to keep bin fill-levels clustered/uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progression Scaling: As we approach the end of the stream, 
    // prioritize packing tightness over future-proofing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize dead space (post_residual) while penalizing fragmentation.
    // If post_residual is in the range [1, 9], it is highly likely to be wasted (unusable for items >= 10).
    // We prioritize keeping bins open if they can fit the next item, or closing them if they become too fragmented.

    let mut score = post_residual as f64;

    // Penalty for creating "Dead Zones": post_residual < 10 are almost useless.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Pressure: If we have many open bins, penalize opening a new one heavily.
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0) + (100.0 / (fitting_bins_count as f64 + 1.0));
    }

    // Efficiency: Favor bins that stay closer to the mean_residual to keep bin distribution uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // Progress awareness: As we approach the end of the stream, prioritize closing bins (lower post_residual).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot fit common items).
    // If the post_residual is less than 10, it's likely a "sliver" that will remain empty.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead matching: Reward bins that become a perfect fit for the next item.
    // If post_residual == next_item_size, we effectively clear the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // 3. Pressure management: If we are near the end of the stream, favor filling bins tightly.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    // 4. Global balance: If this bin's residual is significantly better than the mean_residual,
    // we want to prioritize it to prevent creating fragmented bins.
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // 5. New Bin threshold logic:
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    // Only choose it if fitting_bins_count is low or if current bins are too fragmented.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 5.0; // Essential to open
        } else {
            // Heavily penalize opening a new bin if an existing one can fit the item
            // unless the current open bins are very poorly utilized.
            score = 100.0 - (mean_residual * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
