    }

    // 5. Global Balance: Penalize bins that deviate significantly from the mean residual.
    // This encourages a "Best-Fit" behavior by keeping all bins at similar fill levels.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 6. Encourage tight packing by penalizing large post_residuals more heavily 
    // when we have many open bins.
    if open_bins_count > 5 {
