    // 2. Harmonic Class Logic: penalize remainders that create "unfillable" gaps.
    // If post_residual is small but > 0, it's often a "poison" bin.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 3. Lookahead coupling: If next_item_size is large, favor bins that can still accommodate it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 4. Thresholding: If this is the ONLY bin that fits, prioritize it heavily to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // 5. New Bin Penalty: Discourage opening a new bin unless the current fit is catastrophic.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual is already quite low (bins are full)
        if mean_residual > 20.0 {
            score += 60.0;
        } else {
