pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space: we want to minimize wasted space (Best Fit principle).
    let mut score = post_res;

    // Penalty for creating "dead space": if the post_residual is too small to fit common items 
    // but large enough to be inefficient, we penalize it.
    // A quadratic penalty on small residuals helps avoid creating unfillable gaps.
    if post_res > 0.0 && post_res < 10.0 {
        score += 25.0 * (1.0 - post_res / 10.0);
    }

    // Lookahead logic: If the next item is large, we want to reserve space in the current bin 
    // if the current post_residual can accommodate it.
    if next_item_size > 0 {
        if post_res >= next_item_size as f64 {
            score -= 15.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Heuristic for opening new bins: As the stream progresses, we become more conservative.
    // We increase the cost of opening a new bin (bin_residual == bin_capacity) 
    // relative to the mean residual of existing bins.
    if bin_residual == bin_capacity {
        score += 20.0 + (progress * 30.0) + (mean_residual * 0.5);
    } else {
        // If it's the last chance to fit an item into an existing bin, reward it heavily.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Favor bins that are already well-utilized (lower mean_residual) to keep open bins consolidated.
        score += (bin_capacity as f64 - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

