            score += 20.0;
        }
    }

    // Harmonic class logic: Bias towards filling bins to specific thresholds (e.g., 50, 75, 90)
    // We reward residuals that align with multiples of 25 (common packing fractions)
    let remainder = post_residual % 25;
    if remainder < 5 {
        score -= 10.0;
    }

    // If this is the only bin that fits, prioritize it to avoid unnecessary new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
