    // If considering a new bin (bin_residual == bin_capacity), penalize it 
    // relative to the mean residual of existing bins to force utilization
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += mean_residual * 0.8;
        }
        // Penalize opening a new bin heavily if items remain
        if step_index < total_items {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
