    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for "Dead Space" creation: 
    // Gaps smaller than 10 are almost useless for the given item range (10..80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Heuristic: If this is the only bin that fits the current item, prioritize it heavily
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Lookahead: If the next item is large, avoid leaving a residual that is too small 
    // to accommodate it (e.g., if next_item_size > post_residual).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }

    // Global pressure: If we have many open bins, penalize opening new ones.
    // If we have few open bins, we can afford to be more selective (Best Fit).
    if is_new_bin {
        score += (open_bins_count as f64 * 2.5);
        // As the stream progresses, become increasingly conservative about opening new bins.
        score += (progress * 30.0);
    } else {
        // Reward filling bins that are already "denser" than the current mean
