    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Thresholding: If this is the only bin that can fit the item, prioritize it 
    // to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. New Bin Threshold: If we are considering a new bin (bin_residual == bin_capacity),
    // apply a cost based on the current mean residual of open bins.
    // If open bins are already very full (low mean_residual), opening a new bin is penalized.
    if bin_residual == bin_capacity {
        score += 40.0 + (mean_residual * 0.8);
    }

    // 6. Global Progression: As the stream nears completion, become more aggressive 
    // in packing into existing bins to minimize the total count.
    let progress = step_index as f64 / total_items as f64;
    score -= (progress * 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Strict Best-Fit with aggressive penalty for creating "fragmented" space (gaps < 10)
