    // 3. Global Bin Pressure: 
    // If fitting_bins_count is 1, it's the last chance to place in an existing bin.
    // We prioritize using it unless the fit is extremely poor (post_residual is very large).
    if fitting_bins_count == 1 && post_residual > 40 {
