    // 4. Penalty for opening new bins when capacity is available
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many bins open already (to avoid fragmentation)
        // or if the current best fit is objectively terrible.
        score += (open_bins_count as f64 * 2.5) + 30.0;
    }

    // 5. Prefer bins that keep the mean_residual closer to the item_size, 
