    // We add a non-linear penalty for leaving "dead space" that is too small for common items (e.g., < 20).
    let mut score = post_res * (1.0 + (20.0 / (post_res + 1.0)));

    // Lookahead logic: If the next item is large, penalize small residuals that would strand it.
    if next_item_size > 0 {
        let lookahead_penalty = if post_res < next_item_size as f64 {
            (next_item_size as f64 - post_res) * 1.5
        } else {
            0.0
        };
        score += lookahead_penalty;
    }

    // Progression logic: As the stream nears the end, become more aggressive in packing to avoid opening new bins.
    // We penalize the creation of new bins (bin_residual == bin_capacity) increasingly as progress approaches 1.0.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 + progress * 2.0);
    }

    // Adaptive constraint: If this is the only bin that fits, prioritize it heavily by reducing its score.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Global state coupling: Penalize increasing the number of open bins if the mean residual is already high.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * (mean_residual / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
