            let lookahead_fit = post_residual - next_item_size;
            score -= (100.0 - lookahead_fit as f64) * 0.1;
        }
    }

    // Global state awareness:
    // If we have many open bins, prioritize tightening existing ones.
    // If we are near the end of the stream, be more aggressive about filling bins (lowering score).
    if open_bins_count > 0 {
        score += (open_bins_count as f64) * 0.5 * (1.0 - progress);
    }

    // New Bin Logic:
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    // We only open a new bin if the current "best" fit is truly terrible (high residual).
    if bin_residual == bin_capacity {
        // High threshold to open a new bin: only if existing fits leave large, awkward gaps.
        // We set the new bin score based on the average residual of existing bins.
        score = mean_residual + 20.0;
