    // of other bins, we penalize it to force consolidation.
    if post > mean_residual {
        score += (post - mean_residual) * 0.5;
    }

    // If this is the only bin that can fit the item, reward it highly to prevent
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Non-linear coupling: 
    // Penalize fragmented bins (small post_residual) as the stream progresses
    // to discourage leaving tiny gaps that cannot fit common item sizes.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize dead space 
    // that is too small for common item sizes (10-30 range).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Harmonic Coupling: If the next item fits into the current post_residual,
    // reward this placement to chain items together (Best-Fit-Lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
