    // 4. Harmonic Fragmentation Control: Penalize residuals that are not multiples of common 
    // divisors, favoring residuals that leave room for items like 20, 25, 33, 50.
    if post_residual > 0 {
        let remainder = post_residual % 10;
        score += (remainder as f64) * 2.5;
    }

    // 5. Progression Scaling: As the stream nears the end, become more aggressive 
    // about filling bins to reduce leftover open bins.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
