pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize opening a new bin early in the stream unless it's necessary.
    // As the stream nears completion, allow more flexibility to avoid stranded small items.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 40.0 + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Calculate a "tightness" factor: we prefer to leave as little residual as possible,
    // but we heavily penalize leaving a residual that is too small for any future item
    // (i.e., less than the smallest possible item size, approx 10).
    let dead_space_penalty = if post_residual < 10 && post_residual > 0 {
        25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Factor in the next item: if the current placement prevents the next item 
    // from fitting in this bin, penalize the placement.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        15.0 * (1.0 - (fitting_bins_count as f64 / (open_bins_count as f64 + 1.0)))
    } else {
        0.0
    };

    // Base score is the residual itself, promoting Best-Fit behavior.
    // We adjust by the non-linear penalties derived above.
    let score = post_res + new_bin_penalty + dead_space_penalty + lookahead_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
