    // Global state awareness: If we have too many open bins, penalize opening a new one.
    if is_new_bin {
        score += (open_bins_count as f64) * 5.0;
        // Discourage new bins if we have many bins that could fit the current item.
        score += (fitting_bins_count as f64) * 15.0;
    }

    // Adjust for mean_residual: If this bin's post_residual is significantly worse than
    // the average, apply a penalty to discourage fragmentation.
    if !is_new_bin && (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Time-horizon weighting: As the stream nears the end, prioritize closing bins
    // by aggressively favoring tighter fits.
    if progress > 0.8 {
        score += post_residual as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space. We want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for leaving "fragmented" space that is too small for common items (below 20).
    // The penalty grows as we approach the end of the stream to force tighter packing.
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post) * (1.0 + progress * 2.0);
    }

    // Lookahead logic: if next_item_size is large, avoid bins that leave little space.
    // If next_item_size is 0 (end of stream), prioritize filling up existing bins.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    } else {
        score -= post * 0.5;
    }

    // If this is a new bin (bin_residual == bin_capacity), penalize it based on 
    // how many open bins are available to discourage opening new bins prematurely.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 10.0) * (1.0 - progress * 0.5);
    }

    // Reward bins that bring the bin closer to the global mean residual to keep bins uniform.
    let dev = (post - mean_residual).abs();
    score += dev * 0.2;

    // If this is the last fitting bin, give it a slight preference to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals (near-perfect fills are prioritized)
    // We favor post_residual values that are smaller, but avoid creating "dead space" 
    // that is too small for any future items (typically < 10).
    if post_residual < 10 && post_residual > 0 {
        score += 45.0; 
    }

    // 2. Lookahead Harmonic Coupling:
    // If the next item is large, we want to preserve bins with higher residuals.
    // If the current bin can fit the next item, we lower the score to prioritize this bin.
    if next_item_size > 0 {
        if bin_residual >= (item_size + next_item_size) {
            score -= 20.0;
        } else if bin_residual >= item_size && bin_residual < (item_size + next_item_size) {
            score += 15.0;
        }
    }

