    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless there are no other options (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 10.0;
        }
    }

    // 4. Harmonic Scaling of Mean Residual:
    // If this bin's residual is significantly better than the mean, reward it.
    let residual_diff = (bin_residual as f64) - mean_residual;
    score += residual_diff * 0.5;

    // 5. Progression Scaling:
    // As we approach the end of the stream, prioritize aggressive filling (smaller residuals).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
