    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64;
    }

    // 3. Prevent premature new bin opening: 
    // If this is an existing bin, reduce score to favor reuse over opening a fresh one.
    if bin_residual < bin_capacity {
        score -= 20.0;
    }

    // 4. Balance current bin utilization:
    // If the post_residual is very close to the mean_residual of all bins, 
    // it suggests a balanced distribution.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    // 5. Urgency factor: As we approach the end of the stream, 
    // become more aggressive about fitting items into existing bins.
    let progress = step_index as f64 / total_items as f64;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    // 6. Penalty for creating a new bin unnecessarily:
    // If there are other bins that could fit the item, penalize the empty bin choice.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base penalty for creating "dead space" (small fragments < 10 are often hard to fill)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    }

    // 2. Lookahead optimization: If next item is large, favor keeping space for it.
    // If the current post_residual cannot fit the next item, penalize this bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (next_item_size as f64 / 100.0);
    }

    // 3. Pressure management: If we are running low on bins or at the end of the stream, 
    // be extremely greedy (Best-Fit). If early, allow for better packing configurations.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // High priority to finish a bin rather than starting a new one
        score -= 50.0;
    }

    // 4. New bin logic: Penalize opening a new bin heavily unless the current bins 
    // are nearly full (high mean_residual).
    if bin_residual == bin_capacity {
        score += 40.0;
        // As the stream progresses, make it slightly easier to open a new bin 
        // to avoid sub-optimal late-stage fragmentation.
        score -= (progress * 20.0);
    }

    // 5. Global state normalization: If current mean residual is high, 
    // we have plenty of open space, so prioritize filling tighter.
    if mean_residual > 30.0 {
        score += (mean_residual - 30.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a bin that is too small for the next item.
    // If next_item_size > post_residual, we create "dead space" for the lookahead.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Dynamic pressure: As the stream progresses, increase the penalty for opening new bins.
    // We normalize the influence of open_bins_count against the mean_residual to avoid fragmentation.
    let fragmentation_penalty = (mean_residual - post) * (1.0 - progress);
    score += fragmentation_penalty;

    // Favor bins that are already partially filled to keep the number of open bins low,
    // but modulate this based on the current capacity utilization.
    let utilization_factor = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= utilization_factor * 10.0 * (1.0 + progress);

    // If this is the only bin that can fit the item, prioritize it to avoid creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Discourage opening a new empty bin unless the fit in existing bins is extremely poor.
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep space tight.
    // We normalize the penalty by capacity to maintain scale.
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: Reward placements that leave a residual 
    // that is a multiple of common item sizes (20, 25, 33).
    // This creates "bins of harmony" where future items fit perfectly.
    let harmony_mod = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmony_mod * 0.8;

    // 3. Lookahead Synergy: If the next item fits into the current post_residual,
    // strongly reward this bin to clear the queue.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 4. New Bin Thresholding: Discourage opening a new bin unless the residual
    // is extremely poor (e.g., leaving a large gap that cannot fit common items).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, unless the item is large 
        // or we are near the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += (80.0 - item_size as f64) * 0.5;
        score += (1.0 - progress) * 15.0;
    }

    // 5. Mean residual balancing: Penalize bins that deviate significantly 
    // from the average fullness of existing bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 6. Last-Chance Logic: If this is the only bin that can fit the item,
    // heavily incentivize picking it to prevent unnecessary bin inflation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead" gaps that cannot fit common future items.
    // We prioritize bins that result in a post_residual of 0 (perfect fit).
    // If post_residual is > 0 but < 10 (the minimum item size), it is high-risk "dead space".

    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the resulting gap is smaller than the smallest possible item (10),
    // it is likely useless. Penalize this unless it is a perfect 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Integration: If the next item exists, penalize bins that cannot fit it
    // after the current item is placed.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins (bin_residual == bin_capacity)
    // unless the current open bins are already very full or the item is large.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 35.0;

        // If we have many open bins, penalize opening another one even more
        score += open_bins_count as f64 * 2.0;
    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, 
    // heavily incentivize choosing it to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Efficiency: If the current bin's residual is significantly better than the mean,
    // prioritize it to maintain a balanced packing across all open bins.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins if there are valid alternatives
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 85.0;
    }

    // 2. Best-Fit Decreasing logic: reward smaller post_residuals (tight packing)
    // We treat post_residual as the primary base, but adjust based on lookahead.

    // 3. Lookahead Matching (The "Aggressive 2-step" component)
    // If the next item fits perfectly into the current post_residual, drastically reduce score.
    if next_item_size > 0 {
        if post_residual == next_item_size {
