        } else if post_residual > next_item_size {
            // Reward moderate slack that allows the next item to fit
            score -= 10.0;
        } else {
            // Penalize creating a bin that is too small for the next item
            score += 20.0;
        }
    }

    // 4. Mean Residual balancing: avoid creating "outlier" bins that deviate from average density
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progress-dependent scaling: become more aggressive as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the score.
    // The core strategy balances Best-Fit (minimizing post_residual) with a penalty for 
    // creating "fragmented" small gaps that cannot accommodate future items.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // 1. Base Score: The Best-Fit component (smaller post_residual is better)
    let mut score = post_residual as f64;

    // 2. Penalty for opening a new bin
    // We only open a new bin if the current best existing fit is extremely poor,
    // or if the lookahead suggests we need the space for a specific upcoming item.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if we have existing options
            score += 45.0 + (progress * 20.0);
        } else {
            // If no existing bin fits, opening a new bin is mandatory
            score = 0.0;
        }
    }

    // 3. Fragmentation Penalty:
    // Avoid leaving small gaps (e.g., 1-9) that are unlikely to hold future items.
    // If post_residual is small but > 0, it's often worse than having 0 residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Lookahead Logic:
    // If we have a next item, favor placing the current item in a bin that 
    // leaves enough room for the next item (if possible).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Penalize bins that "block" the next item from fitting here
            score += 10.0;
        }
    }

    // 5. Global State Balancing:
    // Discourage opening too many bins early in the stream.
    if open_bins_count > 5 && !is_new_bin {
        // Encourage using existing bins as we accumulate them
        score -= (open_bins_count as f64) * 0.5;
    }

    // 6. Mean Residual Calibration:
    // If our current bin is significantly "fuller" than the average bin, 
    // favor it to keep the average high (packing efficiency).
    if (bin_capacity - post_residual) as f64 > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize smaller post_residual (Best Fit principle).
    // We apply a non-linear penalty to gaps that are too small to be useful for future items (e.g., < 10).
    let mut score = post;
    if post < 10.0 && post > 0.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Penalty for opening a new bin:
    // If this is an empty bin (new bin candidate), add a cost that scales with 
    // the progress of the stream. Late in the stream, we are more desperate to 
    // consolidate, so opening a new bin becomes increasingly expensive.
    if bin_residual == bin_capacity {
        score += 45.0 + (30.0 * progress);
    }

    // Lookahead coupling:
    // If we have a next item, penalize bins that cannot accommodate it after placing the current one.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Mean residual coupling:
    // Penalize bins that deviate significantly from the mean residual of all open bins.
    // This encourages "leveling" the bins to keep them equally available for future items.
    let deviation = (post - mean_residual).abs();
    score += 0.2 * deviation;

    // Urgency factor:
    // If this is the only bin that can fit the item, give it a significant discount
    // to ensure we don't accidentally open a new bin when a valid one exists.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Minimize post_residual to keep bins tight.
    // We heavily penalize creating small, unusable gaps (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is known, favor placements that leave 
    // exactly enough room for it, or leave enough room for a "heavy" item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that perfectly accommodate the next item (synergy)
            score -= (bin_capacity - post_residual) as f64 * 0.1;
        } else {
            // Penalize placements that block the next item from fitting in this bin
            score += 20.0;
        }
    }

    // 3. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), only pick it if the 
    // fitting_bins_count is 0 (no other choice) or if current open bins are 
    // too fragmented (mean_residual is low).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have fitting alternatives
            score += 150.0 - (mean_residual * 1.5);
        } else {
            // We must open a new bin
            score = 0.0;
        }
    }

    // 4. Harmonic Fragmentation Control:
    // Favor bins that maintain a higher mean_residual across the system to preserve flexibility.
    score += (mean_residual - post_residual as f64) * 0.2;

    // 5. Progression scaling: 
    // As we approach the end of the stream, prioritize closure of existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones": gaps smaller than the smallest possible item (10)
    // but larger than zero, as these are harder to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
