    let is_new_bin = bin_residual == bin_capacity;
    let base_penalty = if is_new_bin { 45.0 } else { 0.0 };

    // Non-linear interaction: Penalize tight fits (very small post_residual) 
    // when we are late in the stream, to leave room for potential future combinations.
    // Use a quadratic term on the inverse of post_residual to favor mid-range residuals.
    let efficiency_penalty = (100.0 - post_res).powf(1.5) * 0.05;

    // Lookahead coupling: If next_item_size is large, penalize small post_residuals
    // that would effectively orphan the current bin.
    let next_item = next_item_size as f64;
