    };

    // Dynamic weighting: As we approach the end of the stream, prioritize closing 
    // bins (lower residual) over saving space for future items.
    let progress_weight = 1.0 - (progress * 0.5);

    let score = base_penalty + (post_res * progress_weight) + efficiency_penalty + lookahead_pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
