    }

    // 4. Distribution Balancing: Avoid creating bins with residuals significantly 
    // lower than the global mean to maintain bin uniformity.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    // 5. New Bin Thresholding: If the bin is brand new (bin_residual == bin_capacity),
