pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing (BFD) logic with a dynamic penalty for fragmentation 
    // and a lookahead bias to preserve space for future items.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: prioritize smaller post-residual (Best Fit)
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": 
    // If the post_residual is small but > 0, it's often better to fill it completely.
    // If the post_residual is between 1 and 9, it's highly likely to remain unused.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead bias: 
    // If we have a next item, check if this bin could fit it after placing current.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (synergy)
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Penalize bins that block the next item from fitting here
            score += 10.0;
        }
    }

    // Global state awareness:
    // If we are late in the stream, be more aggressive to pack tightly.
    // If we are early, be more conservative about opening new bins.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other bins can fit the item
            score += 40.0 + (mean_residual * 0.5);
        }
        // Heavily penalize opening new bins toward the end of the stream
        score += progress * 50.0;
    } else {
        // Reward using existing bins proportionally to how much they deviate from the mean
        // to encourage balancing bin utilization.
        score += (post_residual as f64 - mean_residual).abs() * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalty for creating small, unusable gaps (the "fragmentation" trap).
    // If post_residual is small (e.g., 1-9), it is often worse than a new bin.
    let fragmentation_penalty = if post_residual < 10 {
        25.0 * (10.0 - post_res)
    } else {
        0.0
    };

    // Reward bins that maintain a residual close to the average of existing bins,
    // encouraging clustering of similar-sized items to keep pack density consistent.
    let density_alignment = (post_res - mean_residual).abs() * 0.5;

    // Lookahead logic: if the next item is large, prioritize bins that retain 
    // enough space to accommodate it.
    let lookahead_penalty = if next_item_size > 0 && post_residual < next_item_size {
        15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // New bin bias: Increase the cost of opening a new bin as the stream progresses.
    // At the start, we are more flexible; near the end, we strictly prefer fitting.
    let new_bin_bias = if bin_residual == bin_capacity {
        20.0 + (30.0 * progress)
    } else {
        0.0
    };

    // Interaction term between progress and post_residual to favor tighter fits
    // as we reach the end of the stream (Best Fit style).
    let tight_fit_reward = post_res * (0.5 * progress);

    let mut score = post_res + fragmentation_penalty + density_alignment + lookahead_penalty + new_bin_bias - tight_fit_reward;

    // Favor bins that are the "last chance" to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
