pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "stranded" space:
    // If post_residual is small but > 0, it often creates unusable gaps.
    // We penalize values in the [1, 15] range specifically as they are hard to fill.
    if post_residual > 0 && post_residual < 15 {
        score += 20.0 * (1.0 - (post_res / 15.0));
    }

    // Lookahead coupling:
    // If next_item_size is large, we want to leave enough room in a bin.
    // If next_item_size is small, we can tolerate a tighter fit now.
    if next_item_size > 0 {
        let gap_needed = next_item_size as f64;
        if post_res < gap_needed {
            // Penalize bins that cannot fit the next item if we are mid-stream
            score += (gap_needed - post_res) * (1.0 + progress);
        }
    }

    // Progression adjustment:
    // Toward the end of the stream, prioritize closing bins (lower residual) 
    // over keeping many bins open.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Incentivize filling the last-chance bin to avoid opening a new one
        score -= 10.0 * (1.0 - progress);
    }

    // New bin avoidance:
    // Penalize opening a new bin heavily unless the best fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 20.0);
    }

    // Balancing: Favor bins that stay close to the current mean_residual
    // to keep the bin distribution uniform.
    let dev = (post_res - mean_residual).abs();
    score += dev * 0.1;

