    }

    // 4. New Bin Threshold: If this is a new bin (residual == capacity),
    // only open it if the current best option is very poor.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless existing bins are all poor fits.
        score += 35.0;
