        score += 40.0 * (1.0 + progress.powi(3));

        // If we have fitting bins, opening a new one is almost always bad unless they are all poor fits
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Interaction with mean_residual: penalize bins that deviate significantly from the 
    // current mean to keep bin fill levels uniform (homogenization).
    let deviation = (post - mean_residual).abs();
    score += 0.5 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit base)
    // We prioritize bins that leave the smallest gap.

    // 2. Harmonic Class Logic: Reward placements that leave a residual 
    // which is a multiple of common small item sizes (10, 20, 25).
    let harmonic_penalty = (post_residual % 10) as f64 * 2.5 
                         + (post_residual % 20) as f64 * 1.5;
    score += harmonic_penalty;

    // 3. Lookahead Synergy: If next_item_size fits in the post_residual, 
    // significantly reward this bin to create "perfect" pairs.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.2;
