        }
    }

    // 5. Fragmentation Control: Penalize bins that deviate from the mean residual.
    // This encourages keeping bin residuals tightly packed together.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // 6. Progressive Consolidation: As the stream nears the end, 
    // become more aggressive about filling existing bins (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
