        // or if we have very few fitting bins for the current item
        let openness_penalty = (open_bins_count as f64 * 0.1) + (mean_residual * 0.05);
        score += 15.0 + openness_penalty;

        // As we reach the end of the stream, increase penalty for opening new bins
        score += progress * 20.0;
    } else {
        // Favor bins that bring the residual closer to the mean to consolidate space
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1 * (1.0 - progress);
    }

    // Final scaling: favor bins that are the 'last chance' (fitting_bins_count == 1)
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
