    let mut score = post_residual as f64;

    // Penalty for creating "dead space" (hard to fill gaps < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // Heuristic: If we are near the end of the stream, prioritize aggressive packing.
    if progress > 0.85 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin to keep the packing tight.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // If this is the only bin that fits the item (fitting_bins_count == 1), 
    // force its selection unless it creates a very small, unusable residual.
    if fitting_bins_count == 1 && !is_new_bin {
        if post_residual >= 10 || post_residual == 0 {
            score -= 50.0;
        }
    }

    // Penalty for opening new bins when space is available.
    if is_new_bin {
        if open_bins_count > 0 {
            // Only open a new bin if the current mean_residual is very high 
            // (meaning we have plenty of room elsewhere) or if fitting_bins_count is 0.
            if fitting_bins_count > 0 {
                score += 40.0 + (mean_residual * 0.5);
            } else {
                score -= 10.0;
            }
        }
    }

    // Bias towards balancing the residuals across open bins to prevent isolated "bad" bins.
    let residual_deviation = (bin_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small "dead" residuals that are too small to fit typical future items.
    // We use a quadratic penalty for small residuals to encourage tighter packing.
    let dead_space_penalty = if post > 0.0 && post < 15.0 {
        (15.0 - post).powi(2) * 2.0
    } else {
        0.0
    };

    // Lookahead logic: if the next item fits into the post_residual, reward this bin.
    let lookahead_reward = if next_item_size > 0 && post >= next_item_size as f64 {
        -25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Normalize bin density: punish opening new bins (bin_residual == bin_capacity)
    // as the stream progresses, to encourage consolidating into existing bins.
    let new_bin_penalty = if bin_residual == bin_capacity {
        50.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Interaction with mean_residual: favor bins that keep the global average residual low.
    // This prevents "bin fragmentation" where some bins are nearly full and others are very empty.
    let fragmentation_penalty = (post - mean_residual).abs() * 0.5;

    // Final score: prioritize low post_residual (Best Fit), modulated by lookahead and stream progress.
    let score = post + dead_space_penalty + lookahead_reward + new_bin_penalty + fragmentation_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave the smallest residual
    // Penalty for creating 'dead space' (residuals < 10 are often hard to fill)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Harmonic Coupling
    // If we have a next item, check if this bin could potentially fit it after the current placement.
    // We prioritize bins that leave enough room for the next item (synergy).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can accommodate the next item
        } else {
            score += 10.0; // Penalize bins that 'block' the next item
        }
    }

    // 3. New Bin Thresholding
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless no other bin can fit the item or the remaining space is very inefficiently used.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Discourage opening a new bin if an existing one is available
            score += 45.0 + (open_bins_count as f64 * 0.5);
        } else {
            // Must open a new bin, neutralize the base score
            score = 0.0;
        }
    }

    // 4. Harmonic Density Adjustment
    // Penalize bins that deviate significantly from the mean residual of the system
    // to encourage uniform bin filling (avoiding fragmentation).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progression Scaling
    // Towards the end of the stream, prioritize closing bins (tightest fit)
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
