    // Base score: prioritize smaller post-residual (Best Fit principle).
    let mut score = post;

    // Penalty for opening a new bin: if this is a new bin (bin_residual == bin_capacity),
    // apply a dynamic cost that scales with the progress of the stream.
    // Near the end of the stream, we are more conservative about opening new bins.
    if bin_residual == bin_capacity {
        score += 25.0 + (30.0 * progress);
    }

    // Lookahead logic: if next_item_size is large, favor bins that leave enough space for it.
    // If post_residual is smaller than next_item_size, it's a "bad" fit for the future.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Heuristic coupling: penalize bins that deviate significantly from the mean residual
    // to encourage bin homogenization (keeping bins at similar utilization levels).
    let deviation = (post - mean_residual).abs();
    score += 0.5 * deviation * (1.0 + progress);

    // If this is the last fitting bin, reward it to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
