    }

    // 4. Distributional Balancing: If the residual is much larger than the current mean 
    // of other bins, we are creating an outlier. Penalize high-variance residual distributions.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. New Bin Thresholding: If we are considering a new bin (bin_residual == bin_capacity),
    // add a substantial "opening cost" to force usage of existing bins unless the fit is perfect.
    if bin_residual == bin_capacity {
