    // If we have a large item coming, we prefer to leave a larger gap now to accommodate it later.
    if next_item_size > 50 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open Bins Pressure: Discourage opening new bins unless necessary.
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // Only consider opening a new bin if the number of existing bins is relatively low
        // or if fitting_bins_count is zero (forced).
        if open_bins_count > 0 {
