    }

    // 5. Global state normalization:
    // As the stream progresses, become more aggressive at closing bins (lower scores for tighter fits)
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Mean Residual Balancing:
    // If this bin's residual is significantly lower than the mean, reward it to consolidate space
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

