    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Global state: If we are near the end of the stream, prioritize filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 4. Dynamic pressure: If only one bin fits, we are forced, but avoid creating a new bin if possible.
    // A new bin (bin_residual == bin_capacity) should only be chosen if the score is very low.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Apply a heavy "opening fee" unless the current open bins are all very tight
            score += 45.0 + (mean_residual * 0.5);
        }
    } else {
        // Reward bins that have residuals closer to the mean to keep bin usage balanced
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // 5. Critical constraint: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
