            // Reward bins that maintain enough space for the next item
            score -= 5.0;
        }
    }

    // 4. Global efficiency: Favor bins closer to the mean residual to keep 
    // bin levels balanced (Best-Fit-like behavior).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 5. Progression scaling: As we reach the end of the stream, 
    // become more aggressive about minimizing total bins.
    let progress = step_index as f64 / total_items as f64;
