pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let cap = bin_capacity as f64;

    // Penalty for opening a new bin: proportional to progress to discourage early fragmentation,
    // but scale it by the cost of creating a small residual.
    let is_new_bin = bin_residual == bin_capacity;

    // Core heuristic: Best Fit Decreasing logic modified by lookahead and stream progress.
    // We prioritize bins that result in a small post-residual (tight packing).
    let mut score = post * (1.0 + 0.5 * progress);

    // If this is the only bin that can fit the item, prioritize it heavily to avoid opening a new bin.
