        score -= 50.0;
    }

    // Lookahead interaction: If the next item is large, avoid leaving a tiny, unusable residual.
    // If post_residual is between 1 and 9 (highly likely to be wasted space), penalize.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - progress);
    }

    // If next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 {
