        score -= (item_size as f64) * 0.8;
    }

    // 5. Progression Scaling: As the stream nears the end, prioritize tightly packing existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

