    }

    // 5. New Bin Logic: If bin_residual == bin_capacity, this is a candidate for a new bin.
    // Penalize opening a new bin heavily unless the best fit in existing bins is very poor.
    if bin_residual == bin_capacity {
        score += 35.0; 
        // If it's the very last item, opening a new bin is always the only choice,
        // but if we have open bins, we should favor them.
        if open_bins_count > 0 {
            score += 20.0 * (1.0 - progress);
        }
    }

    // 6. Mean Residual Balancing: Favor bins that stay close to the global mean residual
    // to keep the "fill level" balanced across the bin set.
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin early in the stream, but allow it if it's the only option.
    // The core objective is to minimize post_residual (Best Fit).
    // We apply a non-linear penalty to post_residual based on the proximity to the bin capacity
    // to favor tight packing, while coupling it with the stream progress to become more 
    // conservative (tighter) as the stream nears completion.

    let mut score = post * (1.0 + 0.5 * (1.0 - progress));

    // If this is a new bin (residual == capacity), add a dynamic barrier
    // that discourages opening new bins unless the current options are very poor.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales with the number of bins already in use
        // and the residual space in existing bins.
        score += (mean_residual * 0.8) + (open_bins_count as f64 * 2.0);
    } else {
        // If the bin is already open, reward placements that leave space for the next item.
        // This is a non-linear coupling: if the next item fits into the post_residual,
        // we provide a significant discount.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64 * 0.7);
        }

        // If this is the last chance for the current item, prioritize it heavily
        // to avoid creating unnecessary new bins later.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Quadratic penalty for creating "fragmented" space (small, useless residuals)
    // which are harder to fill as the stream progresses.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

