            score += 50.0; // Strongly penalize opening new bins unnecessarily
        }
    }

    // 5. Density management: Prefer bins that are getting fuller
    // We penalize bins that have a high residual after the item is placed
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // 6. Final adjustment based on fitting availability
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Last chance to fit in an existing bin, incentivize this
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
