    // If we are late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // New bin penalty: increases as we progress to force consolidation.
        score += 35.0 + (progress * 25.0);
    }

    // 4. Mean Residual Awareness:
    // Avoid creating bins that are significantly "worse" than the current average.
    if (post_residual as f64) > mean_residual {
