    // reward this placement to keep the "next" item from forcing a new bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening a new bin if we have many bins already open,
    // unless the current fit is exceptionally good (near-zero post_residual).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 4. Tight Fit Reward: Strongly favor bins that result in a perfect or near-perfect fill.
    if post_residual == 0 {
        score -= 10.0;
    } else if post_residual < 5 {
        score -= 5.0;
    }

    // 5. Global Efficiency: If this bin is the last chance for the item (fitting_bins_count == 1),
    // reduce the penalty for a poor fit to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but prioritize fits that leave space 
    // for the next_item_size or keep the bin close to the population mean.

    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin unless the current fit is extremely poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy premium.
    if bin_residual == bin_capacity {
        score += 45.0; 
