    // 2. Lookahead optimization: If the next item fits perfectly into the post_residual,
    // reward this bin significantly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward fits that leave exactly enough space for the next item (tight packing).
            let diff = (post_residual - next_item_size) as f64;
            score -= (15.0 - diff).max(0.0);
        } else {
            // Penalize if we are creating a gap that fits nothing useful (dead space).
            score += 5.0;
        }
    }

    // 3. Balancing: Favor bins that stay near the mean_residual to keep bin distribution uniform.
    // This reduces the variance of open bins, making it easier to fit future items.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 4. Scarcity adjustment: If this is the last fitting bin, prioritize it to avoid 
    // the penalty of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
