        // We only open a new bin if the "best" existing bin is extremely inefficient.
        score = 85.0 + (open_bins_count as f64 * 2.5) + (progress * 10.0);
    } else {
        // Best-Fit strategy: prioritize filling the bin as much as possible (min post_residual).
        // Penalty for leaving a "sliver" (fragmentation risk):
