        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }

        // Urgency: If this is the only bin that can fit the item, prioritize it strongly.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "slivers" (very small, unusable gaps) that increase with progress.
    // As the stream nears completion, we become more sensitive to small residuals.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * (1.0 + progress * 5.0);
    }

    // Lookahead logic: if the next item can fit in the current post_residual, reward this bin.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // fitting bins are available. We only want to open a new bin if the existing fits are "bad".
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many existing bins that could take it.
        score += (fitting_bins_count as f64) * 25.0;
        // Early in the stream, we are more conservative about opening new bins.
        score += (1.0 - progress) * 50.0;
    } else {
        // If it's an existing bin, reward it if it's close to the mean residual to keep bins balanced.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Final non-linear dampening to prioritize tight fits over empty bin creation.
    score.powf(1.05)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Favor bins that leave the smallest residual (Best Fit).
    // The base score is already post_residual, which heavily weights this.

    // 2. Penalty for creating "dead space": If post_residual is very small but > 0, 
    // it often prevents larger items from fitting later. 
    // If post_residual is between 1 and 9, penalize it heavily.
    if post_residual > 0 && post_residual < 10 {
