    }

    // 4. Harmonic coupling: If the residual is a simple fraction of capacity, 
    // it likely accommodates specific item classes well.
    if post_residual % 25 == 0 {
        score -= 10.0;
    }

    // 5. If this is the only bin that fits, we are forced to use it.
    // However, if the score is still too high, we might prefer a new bin.
    if fitting_bins_count == 1 && post_residual < 15 {
        score += 20.0;
    }

    // 6. Avoid opening a new bin unless the current best options are poor.
    // A new bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high.
        score = 65.0;

        // If we are early in the process, opening a new bin is less costly.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 20.0;

        // If current bins are very full, opening a new one is more justified.
        if mean_residual < 20.0 {
