    // 4. Critical Thresholding: If this is the only bin that can fit the item, prioritize it strongly
    // to avoid unnecessary fragmentation or wasted capacity in other bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Progression Weighting: As the stream nears completion, become more aggressive about filling
    // existing bins to prevent leaving items for the final new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

