    let uniformity_bonus = (post_res_f - mean_residual).abs() * 0.1;

    // Combine factors
    // We prioritize lower scores; new_bin_penalty ensures we only open new bins when existing ones are poor fits
    let score = gap_penalty + new_bin_penalty + next_item_penalty + uniformity_bonus;

