pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let res_sq = post_res * post_res;

    // Penalize the creation of a new bin (where bin_residual == bin_capacity) 
    // unless the fit is exceptionally poor in existing bins.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin { 250.0 + (progress * 150.0) } else { 0.0 };

