        if next_item_size > (post_residual as u32) {
            (10.0 - post_res) * 5.0
        } else {
            (10.0 - post_res) * 20.0
        }
    } else {
        0.0
    };

    // Interaction term: If we are near the end of the stream (progress -> 1.0), 
    // prioritize clearing bins with smaller residuals to consolidate space.
    let consolidation_factor = (mean_residual * progress) * 0.5;

