    let urgency_bonus = if fitting_bins_count == 1 && !is_new_bin { -100.0 } else { 0.0 };

    let score = res_sq + new_bin_penalty + dead_zone_penalty + consolidation_factor + lookahead_bonus + urgency_bonus;

