pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic Logic: Favor post_residuals that are multiples of common item sizes 
    // or leave space for likely future items.
    let harmonic_penalty = if post_residual > 0 {
        // Penalize residuals that are too small to fit typical items (10-30)
        if post_residual < 10 { 25.0 } 
        // Reward residuals that are perfect multiples of 20 (common divisor of 100)
        else if post_residual % 20 == 0 { -15.0 }
        else { 0.0 }
    } else {
        // Perfect fit is highly desirable
        -50.0
    };

    // Lookahead logic: If the next item can fit in the current post_residual, prioritize this bin.
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -30.0 * (post_residual as f64 / bin_capacity as f64)
    } else {
        0.0
    };

    // Pressure logic: If this is the last fitting bin, avoid opening a new one unless the fit is terrible.
    let pressure_factor = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -40.0
    } else if bin_residual == bin_capacity && fitting_bins_count > 0 {
        // Penalty for opening a new bin prematurely
        50.0 + (open_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Global distribution alignment:
    // If the residual is significantly higher than the global mean, we are likely creating wasted space.
    let waste_penalty = if (post_residual as f64) > mean_residual {
        (post_residual as f64 - mean_residual) * 0.5
    } else {
        0.0
    };

    score += harmonic_penalty + lookahead_bonus + pressure_factor + waste_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
