    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.5;

    // 5. Progression Scaling: As the stream nears the end, be more aggressive about closing gaps.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // The base score is the post_residual, favoring Best-Fit.
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin prematurely.
    // If this is the new empty bin (bin_residual == bin_capacity) and other bins can fit the item, 
    // penalize it heavily unless the current open bins are very full.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 200.0 - (mean_residual * 2.0);
    }

    // 2. Lookahead matching: reward bins where post_residual is close to next_item_size.
    // If next_item_size fits in the post_residual, we create a perfect pair.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect or near-perfect fit for the next item
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.8;
        } else {
            // Penalize leaving a sliver that is too small for the next item
            score += 15.0;
        }
    }

    // 3. Density maintenance:
    // If we have many open bins, prioritize filling the ones that are already emptier 
    // to keep the number of active bins from exploding.
    if open_bins_count > 5 {
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // 4. Criticality:
    // If this is the last fitting bin, we treat it with high priority to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: only do it if the fit is very poor or we are near the end
    if is_new_bin {
        // If there are other bins that can fit this, discourage opening a new one
        if fitting_bins_count > 0 {
            score += 100.0 * (1.0 - progress);
        }
        // If we are at the end of the sequence, opening a new bin is very expensive
        score += 50.0 * progress;
    } else {
        // Heavily reward filling a bin completely (Exact Fit)
        if post_residual == 0 {
            score -= 40.0;
        }

        // Lookahead: If the next item fits into the current post_residual, prioritize this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }

        // Avoid creating "unusable" space (small gaps)
        // If the remaining space is too small for any item (assuming min item size ~10)
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }

        // Global state heuristic: balance the load. If this bin's residual is 
        // significantly higher than the mean, prefer placing here to keep it "tight"
        if (bin_residual as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // Dynamic horizon: as we reach the end of the stream, prioritize tight packing (lower residuals)
    // to avoid leaving fragmented bins open.
    score += (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement (Best Fit principle).
    // Lower post_residual is better, so it naturally minimizes.
    let mut score = post_res;

    // Penalty for creating "dead space" that is likely too small for future items.
    // If post_residual is small but > 0, it's often a "fragmentation" trap.
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: If the next item is large and cannot fit in the post_residual,
    // penalize this bin to preserve it for smaller items or force a better fill.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 15.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive 
    // about filling bins tightly to avoid trailing waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // If this is the only bin that fits the item, heavily reward picking it 
        // to avoid opening a new bin prematurely.
        score -= 50.0 * (1.0 - progress);
    }

    // Interaction between mean_residual and current post_residual:
    // If our current choice makes the bin significantly worse than the average, penalize it.
    let residual_delta = post_res - mean_residual;
    if residual_delta > 0.0 {
        score += residual_delta * 0.5;
    }

    // New bin logic: If bin_residual == bin_capacity, this is a "new bin" candidate.
    // Only choose a new bin if the score is very low (i.e., we are forced to).
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low,
        // or if we are very early in the stream where packing density matters less.
        score = 40.0 + (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // We prioritize bins that leave very little space (Best-Fit principle).
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic:
    // If post_residual is small, it might be unusable for future items.
    // We penalize "sliver" residuals (e.g., 1-9) which are rarely useful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Integration:
    // If the next item can fit in the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Fitting Constraint:
    // If this is the only bin that can fit the item, aggressively favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // 5. Empty Bin Threshold:
    // Penalize opening a new bin unless the current mean_residual is highly fragmented.
    if bin_residual == bin_capacity {
        // As the stream progresses, getting closer to the end, discourage new bins.
        let progress = step_index as f64 / total_items as f64;
        score += 30.0 + (progress * 20.0);

        // If we have many open bins, opening another is expensive.
        score += open_bins_count as f64 * 2.0;
    }

    // 6. Harmonic Balancing:
    // Favor bins whose current state aligns with common item size distributions (e.g., 25, 33, 50).
    let alignment = (post_residual % 25) as f64;
    score += alignment * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is likely unusable.
    // We heavily penalize creating small gaps that are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless the current fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), add a significant penalty.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead Synergy: If we know the next item, favor placements that leave enough 
    // room for it, or conversely, prioritize filling a bin that won't fit the next item anyway.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (Best Fit optimization)
            score -= 15.0;
        } else if post_residual < 10 && post_residual > 0 {
            // Penalize leaving a gap too small for the next item if the next item is large
            score += (next_item_size as f64) * 0.2;
        }
    }

    // 4. Fitting Constraint: If this is the last chance for the current item (fitting_bins_count == 1),
    // and it's not a new bin, reward it to prevent unnecessary bin proliferation.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // 5. Global Density: If the mean residual is high, we are currently wasting space.
    // Tighten the heuristic by penalizing larger post_residuals.
    if mean_residual > 20.0 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small fragments that are unlikely to fit future items.
    // Small residuals (1..10) are "dead zones" because min item size is often larger.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2. Lookahead Coupling: If next_item_size can fit into the post_residual, reward this bin placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Further reward if it creates a perfect or near-perfect fit for the next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. Mean Residual Balancing: Avoid deviating too far from the average state of open bins.
    // This prevents creating "outlier" bins that are much emptier/fuller than current ones.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 4. Strategic New Bin Threshold: 
    // If this is a new bin (bin_residual == bin_capacity), penalize opening it unless the 
    // current fitting options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is high.
        score += 35.0;

        // If we have many bins open, discourage opening more unless necessary.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // If it's an existing bin and it's the last chance (fitting_bins_count == 1),
        // we prioritize it slightly to prevent orphan bins.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 5. Progression Scaling: As the stream nears the end, prioritize closing existing bins (packing tighter).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
