}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (dead space) quadratically to favor tight packing
    // but allow flexibility early in the stream.
    let dead_space_penalty = if post < 10.0 {
        (10.0 - post).powf(2.0) * 1.5
    } else {
        0.0
    };

    // Factor in the impact of the next item. If the current placement makes it 
    // impossible to fit the next item, penalize proportionally to the next item's size.
    let lookahead_penalty = if next_item_size > post_residual && next_item_size > 0 {
        (next_item_size as f64 - post) * 2.0
    } else {
        0.0
    };

    // Reward utilizing bins that are already "open" to consolidate space.
    // As the stream progresses, increase the penalty for opening new bins (bin_residual == capacity).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (open_bins_count as f64 * 0.5) + (progress * 50.0)
    } else {
        0.0
    };

    // Interaction term: penalize bins that deviate from the mean_residual
    // to encourage uniform fill levels across the active set.
    let imbalance_penalty = (post - mean_residual).abs() * 0.5;

    // Final score: prioritize lower post_residual (Best Fit), modulated by constraints
    let score = post 
        + dead_space_penalty 
        + lookahead_penalty 
        + new_bin_penalty 
        + imbalance_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
