        score -= fit_next * (next_item_size as f64 * 0.8);
    }

    // 3. Last chance logic: If this is the only bin that fits, heavily favor it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 4. New bin penalty: Heavily penalize opening a new bin unless it's the only choice or very efficient
    if bin_residual == bin_capacity {
        score += 35.0;
        // If we have many open bins, penalize opening another one (load balancing)
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Modulo-based "Perfect Fit" reward: Encourage filling bins to high capacity
    // Rewards residuals that are multiples of 5 or 10, as they are likely to fit future items
    let remainder = post_residual % 5;
    if remainder == 0 {
        score -= 5.0;
    }

    // 6. Progress-based scaling: As stream progresses, be more conservative with residuals
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
