    // Dynamic density pressure: As the stream progresses, prioritize closing bins (lower mean_residual).
    // We penalize bins that keep the mean_residual high relative to the current post_residual.
    let density_penalty = (mean_residual - post_res) * progress * 5.0;
    score += density_penalty;

    // Penalty for opening a new bin: Only open if the score is extremely low.
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
