        score += open_bins_count as f64 * 2.0;
    } else {
        // For existing bins, prioritize bins that, after this item, 
        // leave a residual close to the average of other bins (clustering).
        let diff_from_mean = (post - mean_residual).abs();
        score += diff_from_mean * 0.5;

        // If the next item is large, prioritize bins that have enough space for it.
        if next_item_size > 0 && post < next_item_size as f64 {
            score += 40.0;
        }

        // If this is the last fitting bin, give it a slight preference to avoid opening a new one,
        // unless the residual is very small (creating a dead-end).
        if fitting_bins_count == 1 && post > 5.0 {
