    // We penalize larger post_residuals to encourage filling bins as much as possible.
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic: Reward residuals that are multiples of common item sizes (e.g., 20, 25, 33).
    // This creates "bins" of potential future items.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.8;
    score += harmonic_penalty;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
