    // 4. New Bin Threshold: If this is an empty bin (new bin candidate), penalize it 
    // unless we are forced to (e.g., fitting_bins_count is low or residual is very tight).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have plenty of open bins.
        score += 45.0 + (open_bins_count as f64 * 2.5);
    } else {
        // Reward using existing bins.
        score -= 5.0;

        // If this is the last chance for the current item, lower the penalty for a poor fit.
        if fitting_bins_count == 1 {
