        }
    }

    // 5. Mean residual equilibrium: Penalize bins that deviate significantly from the mean 
    // to keep the bin distribution uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 6. Progression scaling: As we approach the end of the stream, prioritize packing 
