    // If a bin has a small residual that is likely too small for future items, 
    // it effectively wastes that space. Penalize residuals < 10 (hard to fill).
    if !is_new_bin && post_residual < 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 3. Lookahead Logic:
    // If we have a next_item, avoid creating a bin that makes the next item impossible to place.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize if this placement prevents the next item from fitting in this bin.
            score += 15.0;
