}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: remaining space after placement.
    // We want to minimize post_residual (Best Fit), but penalize creating "splinters" (unusable space < 10).

    let mut score = post_residual as f64;

    // 1. Splinter Penalty: If the remaining space is too small to fit any expected future items (min 10),
    // it is likely wasted. Penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
