    // 3. Global State: If we have many open bins, prioritize tightening existing bins (Best Fit).
    // If few bins are open, be more conservative about keeping space open.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    if open_bins_count > 5 {
        score += fill_ratio * 10.0;
    }

    // 4. New Bin Logic: If bin_residual == bin_capacity, it's a new bin.
    // Only open a new bin if the current best fit is objectively terrible (post_residual > 20).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Must open
        } else {
