    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that leave exactly enough space for the next item (perfect match)
            score -= (100.0 - (post_residual - next_item_size) as f64).sqrt() * 5.0;
        } else {
            // Penalize bins that leave just enough space to be unusable for the next item 
            // but too little for future flexibility.
            score += 15.0;
        }
    }

    // 3. New Bin Penalty:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless we are forced to (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 85.0; 
        }
    }

    // 4. Global distribution awareness:
    // If post_residual is significantly lower than the current mean_residual,
    // it implies this bin is becoming more efficient than the average.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. Final constraint:
    // Discourage creating bins that are nearly empty if we have many open bins.
    if open_bins_count > 5 && post_residual > 70 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // However, avoid creating "orphaned" small residuals (e.g., < 10) 
    // unless it's the very end of the stream.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // 2. Lookahead Integration: If the next item is large, prioritize 
    // keeping large residuals. If the next item is small, prioritize tight fits.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // This bin cannot fit the next item; penalize slightly.
            score += 15.0;
        } else {
            // This bin can fit the next item; reward slightly.
            score -= 5.0;
        }
    }

    // 3. New Bin Handling: If bin_residual == bin_capacity, this is a new bin.
    // We only want to open a new bin if the current fit options are poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if existing ones can fit the item,
            // unless the current mean_residual is very low (bins are full).
            score += 40.0 - (mean_residual * 0.5);
        } else {
            // No choice, must open new bin.
            score = 0.0;
        }
    }

    // 4. Global State: As the stream progresses, become more aggressive 
    // about filling existing bins to minimize the final bin count.
    score += (open_bins_count as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Heuristic: Best-Fit Decreasing logic augmented with lookahead and stream density.
    // 1. Penalize new bins heavily early in the stream, but allow them if the fit is perfect.
    // 2. Minimize post_residual, but apply a non-linear curvature to prioritize tight fits.
    // 3. If next_item_size is large, penalize small post_residuals that could block future fits.

    let mut score = post.powf(1.5);

    // Penalty for opening a new bin
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 + progress) * (1.0 + mean_residual / 10.0);
    }

    // Lookahead: If the next item is large, avoid leaving a residual that is too small for it.
    if next_item_size > 0 && post < next_item_size as f64 {
        // If the current bin is the only one fitting the current item, avoid creating a "dead" zone
        if fitting_bins_count == 1 {
            score += 40.0 * (1.0 - progress);
        } else {
            score += 15.0;
        }
    }

    // Reward bins that bring the mean residual closer to a target "tightness" (e.g., 5-10 units)
    let target_tightness = 8.0;
    score += (post - target_tightness).abs() * 0.5;

    // Discourage excessive bin fragmentation
    score += (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

