    // Heuristic for opening new bins:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // all existing open bins would result in a very poor fit (e.g., leaving a small, unusable gap).
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the average 
        // residual is already quite low, implying we should keep our options open.
        score += 35.0 + (open_bins_count as f64 * 0.5);
    }

    // Tight fit incentive: If this bin is the last one that can fit the item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Adaptive smoothing: Use mean_residual to avoid creating bins that deviate 
    // too far from the current strategy's average efficiency.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // Progression factor: As we approach the end of the stream, prioritize 
    // tighter packing to close out bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
