        let deviation = (post as f64 - mean_residual).abs();
        score += deviation * 2.0;
    }

    // Heuristic: If this is the only bin that can fit the item, prioritize it heavily
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Non-linear coupling: penalize very small residuals late in the stream
    // to keep space available for potentially large items.
    if post < 10.0 && progress > 0.7 {
