        } else if gap_after_next < 10.0 {
            score -= 20.0;
        }
    }

    // 3. Open Bin Pressure: If this is a new bin, penalize it based on how many bins are already open.
    // This forces the heuristic to prioritize filling existing bins before spawning new ones.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // If there are other bins that could fit the item, make the new bin very unattractive.
        if fitting_bins_count > 0 {
            score += 60.0;
        }
    }

    // 4. Mean Residual Balancing: Prefer bins that stay close to the global mean residual to 
    // keep bin contents uniform, preventing "bin starvation" where one bin is too full to accept anything.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // 5. Progression Weighting: Towards the end of the stream, aggressively prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
