            score -= (bin_capacity - bin_residual) as f64 * 0.15;
        }
    }

    // Reward bins that keep the mean residual closer to the ideal 
    // This helps avoid fragmentation across many bins
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
