pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Minimize this to pack tightly (Best Fit).
    let mut score = post;

    // Penalty for creating "stranded" space: if the post-residual is small but > 0, 
    // it is often harder to fill than a slightly larger residual.
    // We add a non-linear penalty for residuals in the [1, 9] range.
    if post > 0.0 && post < 10.0 {
