    // we give this placement a strong preference (lowering the score).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Harmonic/Fractional logic: Reward bins that become "full" (residual near 0).
    // Specifically target multiples of 20 to align with common item size distributions.
    let remainder = post_residual % 20;
    if remainder == 0 {
        score -= 10.0;
    }

    // New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // fitting_bins_count is 0 (meaning no other bin can fit the item).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score -= 5.0;
        }
    }

    // Density normalization:
    // As the stream progresses, favor packing tighter to prevent fragmentation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    // Final adjustment based on mean residual:
    // If our current post_residual is better (lower) than the average, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post = post_residual as f64;
