pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // The "Best Fit" behavior is promoted by penalizing post_residual^2,
    // but we adjust the curvature based on stream progress.
    let fragmentation_penalty = post.powf(1.5 + progress);

    // Lookahead logic: if next_item_size is large, favor keeping bins open that have
    // enough space to accommodate it.
    let next_item = next_item_size as f64;
    let lookahead_penalty = if next_item > post && next_item > 0.0 {
        (next_item - post).powf(1.2) * 2.0
    } else {
        0.0
    };

    // If this is a new bin, apply a significant base penalty that decays as the stream progresses,
    // encouraging packing into existing bins early, but allowing new bins if existing ones are poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (25.0 * (1.0 - progress)) + (mean_residual * 0.5)
    } else {
        0.0
    };

    // Favor bins that have a residual closest to the average to maintain uniform packing density.
    let balance_penalty = (post - mean_residual).abs() * 0.2;

    // If fitting_bins_count is 1, we are at a "last chance" scenario for this bin.
    // Reduce penalty to encourage filling it rather than opening a new one.
    let urgency_factor = if fitting_bins_count == 1 { 0.5 } else { 1.0 };

    (fragmentation_penalty + lookahead_penalty + new_bin_penalty + balance_penalty) * urgency_factor
}

