pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: prioritize tighter fits (smaller post_residual).
    // The penalty for new bins is scaled by progress to become more conservative near the end of the stream.
    let mut score = post * post;

    // Penalty for creating a new bin:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    if bin_residual == bin_capacity {
        // We penalize opening a new bin heavily early on, but reduce the barrier as the stream progresses
        // to avoid being stuck with high residuals in existing bins.
        score += 2500.0 * (1.0 - progress * 0.5);
    }

    // Lookahead interaction:
    // If next_item_size exists, penalize post_residual if it's too small to accommodate the next item.
    // This effectively implements a soft Best-Fit-Decreasing behavior.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 15.0;
        }
    }

    // Pressure normalization:
    // If we have many open bins, we want to favor filling them (lower score) to keep the packing density high.
    // If open_bins_count is high, we subtract from the score to make filling them more attractive.
    score -= (open_bins_count as f64).sqrt() * 10.0;

    // Avoid leaving "unusable" small gaps:
    // If post_residual is small but not zero (e.g., 1-9), it's often dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits (Best-Fit-Decreasing logic).
    // We penalize larger post_residuals to encourage filling bins as much as possible.

    // 2. Lookahead integration: If next_item_size is large, avoid leaving a small gap that 
    // cannot accommodate future items. If next_item_size fits in the post_residual, reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Strong reward for keeping space for the next item
        } else if post_residual > 0 && post_residual < 20 {
            score += 40.0; // Strong penalty for "fragmentation" (creating unusable slivers)
        }
    }

    // 3. Harmonic/Modulo logic: Favor residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // to keep the bin state "clean" for future items.
    let remainder = post_residual % 25;
    score += remainder as f64 * 0.5;

    // 4. Global state management:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless no other bin fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing bin could take the item.
            score += 150.0;
        } else {
            // Base cost for opening a new bin.
            score += 10.0;
        }
    }

    // 5. Progression scaling: As we approach the end of the stream, 
    // prioritize closing open bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 6. Mean residual balancing: Penalize bins that are significantly emptier than the average.
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

