    }

    // 2. Open Bins Pressure: Penalize opening new bins when space is available.
    // If this is a new bin (bin_residual == bin_capacity), add a cost proportional to open bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.5) + 15.0;
