            score += 20.0;
        } else {
            // Reward bins that can accommodate the next item
            score -= 10.0;
        }
    }

    // 4. Fitting Constraint: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global Efficiency: If the current bin is very empty (high residual), 
    // discourage using it if we have many bins open, to encourage consolidation.
    if bin_residual > 80 && open_bins_count > 5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to prioritize tight packing.
    // We favor bins where the post_residual is small.
    score += (post_residual as f64) * 1.5;

    // 2. Lookahead Synergy: If the next item fits perfectly into the resulting post_residual, 
    // significantly reduce the score to prioritize this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.8;
    }

    // 3. New Bin Aversion: Heavily penalize opening a new bin unless the current
    // fitting_bins_count is low or the residual is extremely inefficient.
    if bin_residual == bin_capacity {
        score += 85.0; // Base cost to open a new bin
        if fitting_bins_count > 0 {
            score += 50.0; // Aggressive penalty if existing bins could have taken it
        }
    }

    // 4. Mean Residual Balancing: If the post_residual is significantly better than the 
    // current mean, reward the bin to keep the packing density uniform.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. Last Chance Optimization: If this is the only bin that can fit the item,
    // lower the score to ensure it is picked over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Penalize large remaining space to encourage tight packing.
    // We use exponential growth to heavily penalize "wasted" space.
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Synergy: If the next item fits into the current post_residual,
    // we prioritize this bin to reduce the number of bins opened in the next step.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Global Efficiency Bias: If we are late in the stream, be more conservative 
    // about opening new bins. If early, allow more flexibility.
    if is_new_bin {
        // Penalty for opening a new bin scales with progress to discourage fragmentation late-game
        score += 50.0 + (progress * 100.0);
    } else {
        // If this bin is the only one that fits the current item, reward it to prevent 
        // unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // 4. Mean Residual Coupling: If the post_residual is significantly better than 
    // the global average, prioritize it to keep the "average bin" density high.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. Thresholding for extreme cases: If a bin is nearly full (residual < 10), 
    // it is usually a high-value candidate regardless of other factors.
    if post_residual < 10 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_res;

    // Penalize creating "dead space" (very small residuals that are hard to fill later)
    // We penalize residuals in the (0, 10] range heavily as they are likely wasted.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: If the next item is large, prioritize keeping space open.
    // If next_item_size is large (> 60), we bias against bins that leave little room.
    if next_item_size > 60 {
        score += (next_item_size as f64 - post_res).max(0.0) * 0.5;
    }

    // Dynamic Pressure: As we approach the end of the stream, prioritize 
    // filling existing bins (minimizing open_bins_count) over perfect packing.
    let fill_urgency = progress * 20.0;
    score -= (open_bins_count as f64) * fill_urgency;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), add a significant penalty
    // unless the current best fit is objectively terrible (post_residual < 5).
    if bin_residual == bin_capacity {
        score += 45.0 - (progress * 15.0);
    }

    // Coupling: If fitting_bins_count is 1, this is the only bin that can take the item.
    // We reward this heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Smoothing: Penalize deviations from the mean_residual to keep bin fullness uniform.
    let residual_diff = (post_res - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Best-Fit Decreasing / Harmonic-inspired heuristic:
    // We aim to minimize the residual space (Best Fit) while penalizing splits that 
    // leave "unusable" gaps (below 10, the minimum item size).

    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to increase packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // If this is a new bin, penalize it relative to the average efficiency of existing bins.
    // We only open a new bin if the existing options are very poor (high residuals).
    if bin_residual == bin_capacity {
        score = mean_residual * 1.5;

        // If we have very few bins open, we are more willing to open a new one.
        if open_bins_count < 2 {
            score -= 10.0;
        }
    }

    // Reward bins that are nearing capacity (Best Fit principle).
    // The closer to 0 post_residual, the better, but we prioritize bins that 
    // are already partially filled.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    // If fitting_bins_count is 1, this is the only bin that can take the item.
    // If it's a poor fit (high post_residual), we might prefer a new bin.
    if fitting_bins_count == 1 && post_residual > 40 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

