    // If post_residual is small but not zero, it's highly inefficient.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If next_item_size is known, penalize bins that cannot fit it
    if next_item_size > 0 && post_residual < next_item_size {
