pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow flexibility as the stream ends.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (1.0 - progress) * 50.0 + 20.0
    } else {
        0.0
    };

    // Calculate a "tightness" score. We prefer post_residuals that are close to 0 (Best Fit),
    // but penalize very small residuals (e.g., 1-3) that are likely to become stranded dead space.
    let tightness_penalty = if post < 5.0 && post > 0.0 {
        (5.0 - post) * 15.0
    } else {
        post
    };

    // Lookahead logic: if the next item fits into the post_residual, reward this placement.
    let lookahead_reward = if next_item_size > 0 && next_item_size <= post_residual {
        -25.0 * (1.0 - (post / bin_capacity as f64))
    } else {
        0.0
    };

    // Interaction term: If we have many fitting bins, be more selective.
    // If fitting_bins_count is low, be more aggressive about filling even if residual is large.
    let selectivity = (fitting_bins_count as f64).ln() * 5.0;

    // Combine features:
    // 1. Base penalty on remaining space (post_residual)
    // 2. Add penalty for new bins (weighted by progress)
    // 3. Add reward for potential next-item fit
    // 4. Adjust by current bin density via mean_residual
    let score = tightness_penalty 
        + new_bin_penalty 
        + lookahead_reward 
        + selectivity 
        + (mean_residual * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
