    // to keep the number of open bins low.
    let density_penalty = (open_bins_count as f64) * (1.0 - progress);
    score += density_penalty * 5.0;

    // Lookahead logic: if next_item_size fits in the current post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (100.0 - (post / bin_capacity as f64 * 100.0));
    }

    // New bin candidate logic:
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Penalize this heavily unless we are forced to (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other options exist
            score += 150.0 + (100.0 * (1.0 - progress));
        } else {
