    // 2. Lookahead matching:
    // If the next item fits perfectly into the post_residual, reward this placement heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            // If post_residual is slightly larger than next_item, reward proportionally
            score -= (next_item_size as f64 / (post_residual as f64 + 1.0)) * 10.0;
        } else {
            // Penalty if post_residual is too small for the next item, creating fragmentation
            score += 15.0;
        }
    }

    // 3. Mean Residual Balancing:
    // Avoid creating bins that are significantly below the current mean residual
    // (which usually indicates an inefficient, cluttered bin).
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 20.0;
    }

    // 4. Critical Threshold Protection:
    // If this is the only bin that can fit the item, discourage opening a new bin
    // unless the current bin is extremely inefficient.
    if fitting_bins_count == 1 && bin_residual == bin_capacity {
        score += 50.0;
    }

    // 5. Final refinement: Favor tight fits (Best Fit principle)
    // The lower the post_residual, the better, but tempered by the lookahead logic.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

