    // we only pick it if the existing bins are poor fits (high mean_residual).
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early, but reduce penalty as the bin
        // becomes the only logical choice or as we approach the end of the stream.
        score += 40.0 - (mean_residual * 0.3) + (progress * 10.0);
    } else {
