    // We add a quadratic penalty for large residuals to favor tight packing.
    let mut score = post * (1.0 + 0.05 * post);

    // Lookahead interaction: If the next item fits into the current post_residual, 
    // heavily reward this bin to encourage packing pairs.
    if next_item_size > 0 && (post_residual >= next_item_size) {
        score -= 45.0 * (1.0 - progress);
    }

    // Adaptivity: As the stream nears the end, penalize opening new bins heavily 
    // by increasing the cost of the "new bin" candidate (where post == 100 - item_size).
    if bin_residual == bin_capacity {
