    }

    // Penalty for creating "dead space": if the post_residual is too small to fit 
    // common item sizes, it's effectively wasted. We penalize small non-zero residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - progress);
    }

    // Balance open bins: If many bins are open, push the score to favor filling existing ones
    // rather than spreading items across many bins.
    score += (open_bins_count as f64) * 0.5;

    // Critical constraint: If this is the only bin that fits the current item, 
    // ensure it is prioritized over opening a new bin by applying a significant discount.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
