        // 5. Global Mean Alignment: Favor bins that stay near the global mean
        // to keep usage density uniform across active bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 6. Progress Scaling: As the stream nears the end, become more aggressive
    // about closing bins (higher penalty for opening new ones).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (wasted space)
    // 2. New bin thresholding: Apply a dynamic penalty to opening new bins
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: decreases as the stream progresses
        // to ensure we don't starve at the end, but penalizes fragmentation early on.
        score += 25.0 * (1.0 - progress);
    } else {
        // 3. Lookahead optimization (k=2):
        // If the next item fits into the current post_residual, prioritize this bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }

        // 4. Tightness bias: If this is the only bin that fits the current item, 
        // give it a strong preference to avoid creating a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // 5. Global state balancing: 
        // Penalize bins that deviate significantly from the mean residual.
        // We want to keep residual space uniform to maximize packing flexibility.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * deviation;
    }

    // 6. Extreme packing: If the item fits perfectly, reward heavily.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    let post = post_residual as f64;

    // Penalize creating small, unusable gaps (1..10 range is usually dead space)
    // A quadratic penalty on small post_residuals discourages "fragmentation"
    let fragmentation_penalty = if post < 10.0 && post > 0.0 {
        (10.0 - post).powi(2) * 2.5
    } else {
        0.0
    };

    // Reward bins that tightly fit the current item, adjusted by the lookahead
    // If next_item_size is large, we prefer a larger post_residual to accommodate it
    let lookahead_alignment = if next_item_size > 0 {
        let needed = next_item_size as f64;
        if post < needed {
            // Penalize placing current item if it prevents the next item from fitting
            20.0 * (1.0 - (post / needed))
        } else {
            // Reward having just enough space for the next item
            -5.0 * (1.0 - (post - needed) / bin_capacity as f64)
        }
    } else {
        0.0
    };

    // Dynamic scaling: as the stream progresses, favor packing tighter (Best Fit)
    // to minimize the trailing fragmentation at the end of the stream.
    let progression_factor = 1.0 + (progress * 2.0);

    // Base score is the residual; we want to minimize this (Best Fit principle)
    // We modify the residual value to account for the bin's state
    let mut score = post * progression_factor;

    // Add penalties and rewards
    score += fragmentation_penalty;
    score += lookahead_alignment;

    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless no other bin can fit the item or fitting_bins_count is low.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Exponentially discourage opening a new bin if space exists elsewhere
            score += 150.0 / (open_bins_count as f64 + 1.0);
        } else {
            // If it's the only option, make it attractive
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a small, unusable gap (fragmentation avoidance)
    // Residuals between 1 and 9 are often dead space given item range 10-100
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
