    // Harmonic/Density logic: favor filling bins to capacity (Best Fit Decreasing principle)
    // We penalize high residuals more heavily as the stream progresses
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * (1.0 + progress);

    // If this is the only bin that can fit the item, favor it heavily to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // New-bin thresholding: only open a new bin if the best existing fit is extremely poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high; only choose if existing options are terrible
        score += 45.0;

        // If we are nearing the end of the stream, discourage opening new bins
        if progress > 0.9 {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

