    // 3. Global Efficiency: If this is the only bin that can fit the item, we must take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. New Bin Thresholding: Discourage opening a new bin unless the current mean_residual 
    // is too low to accommodate the average item size (approx 50).
    if bin_residual == bin_capacity {
        if mean_residual > 30.0 && open_bins_count > 0 {
            score += 100.0; // Heavily penalize opening new bins if existing ones have space
        } else {
            score += 20.0; // Mild penalty for new bins to favor existing ones
        }
    }

    // 5. Progression Weighting: As the stream nears the end, prioritize closing bins
    // by preferring the tightest possible fit.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
