    let mut score = post_res;

    // Penalty for creating a bin that is too "empty" relative to the current mean.
    // As the stream progresses, we become more aggressive about filling bins tightly.
    let tightness_penalty = (post_res - mean_residual).max(0.0) * progress;
    score += tightness_penalty;

    // Lookahead: If the next item is large, avoid leaving a small, unusable gap.
    // If post_residual is small but > 0 and < next_item_size, it's a "bad" gap.
