    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 1.5);
    }

    // 3. Lookahead Coupling: If next_item_size is large, prioritize bins that leave
    // enough space for it (Best-Fit variant).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that cannot fit the next item if we have other choices
            score += 20.0;
        } else {
