            score -= 10.0;
        }
    }

    // 4. Global Density Awareness: If we are deep into the stream, become more aggressive 
    // about filling bins to reduce the total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (open_bins_count as f64 / 10.0);

    // 5. Fitting Constraint: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
