pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // As post_res approaches 0, the penalty increases sharply to avoid "dead space"
    // unless the bin is exactly full (perfect fit).
    let fragmentation_penalty = if post_res == 0.0 {
        -50.0 // Huge reward for perfect fit
    } else {
        (1.0 / (post_res + 1.0)).powf(1.5) * 20.0
    };

    // Factor in lookahead: if the next item is large, favor keeping space open.
    // If next_item_size is 0 (end of stream), ignore lookahead.
    let lookahead_impact = if next_item_size > 0 {
        let space_needed_for_next = next_item_size as f64;
        if post_res < space_needed_for_next {
            15.0 // Penalize bins that would be too small for the next item
        } else {
            -5.0 // Reward bins that maintain capacity for the next item
        }
    } else {
        0.0
    };

    // Global state: As the stream progresses, become more aggressive in packing
    // (reduce open_bins_count impact).
    let packing_pressure = (open_bins_count as f64) * (1.0 - progress);

    // If this is a new bin (bin_residual == bin_capacity), set a threshold.
    // Only open a new bin if the score is significantly better than current options.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_base = if is_new_bin {
        // Only open new if we have too many open bins already or if fits are very poor.
        if fitting_bins_count == 0 { 0.0 } else { 40.0 + packing_pressure }
    } else {
        0.0
    };

    let score = post_res + fragmentation_penalty + lookahead_impact + new_bin_base;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
