    };

    // Final score: minimize post_residual, minimize dead space, minimize new bin usage.
    let score = (post_res * progress_weight) + dead_space_penalty + lookahead_factor + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic 1221: Harmonic Residue Balancing
    // We prioritize bins that result in 'harmonic' residuals (multiples of common divisors)
    // or leave space that perfectly accommodates the lookahead item.

    let mut score = post_residual as f64;

    // 1. Exact fit reward: Strongest incentive for Best Fit logic
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2. Lookahead optimization: Reward bins that can fit the next item perfectly
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 150.0 / (1.0 + diff);
    }

    // 3. Penalty for "Dead Space" creation: 
    // If post_residual < 10, it's likely unusable for most items. Penalize it.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // 4. Harmonic class bias:
    // Prefer post_residuals that are multiples of 25 (1/4 capacity) or 33 (1/3 capacity)
    // to keep bins aligned for future larger items.
    if post_residual % 25 == 0 {
        score -= 40.0;
    }
    if post_residual % 33 == 0 {
        score -= 30.0;
    }

    // 5. Open bin management:
    // If this is the only fitting bin, lower the threshold to accept it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 6. New bin aversion:
    // Heavily penalize opening a new bin unless the current residual is extremely poor.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Scale by open bins count to discourage fragmentation
        score += (open_bins_count as f64) * 5.0;
    }

    // 7. Global state alignment:
    // If this bin is significantly worse than the current average, penalize it.
    if (post_residual as f64) > mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creation of "unusable" small gaps (dead space < 10, the minimum item size)
    // This forces the algorithm to prefer bins that leave larger, more versatile gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Adaptive pressure: If we have many open bins, penalize opening a new one.
