            score += 15.0; // Penalty for making it impossible to fit next item in this bin
        }
    }

    // 3. Prevent fragmentation: penalize if we leave a bin with a uselessly small residual
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 4. Strategic New Bin usage:
    // If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if the current open bins are all poor fits
            score += 30.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Must open a new bin
            score -= 50.0;
        }
    }

    // 5. Global state balancing:
    // If the mean residual is high, we are currently inefficient; favor packing tighter
    if mean_residual > 30.0 {
        score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;
    }

    // 6. Final progress weighting: tighten constraints as we approach the end of the stream
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

