    // We use the mean_residual to gauge the global state.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 20.0;
    }

    // If we have very few fitting bins, lower the threshold to accept even a poor fit
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0; 
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (fragments too small for common item sizes)
    // We prioritize bins that leave exactly 0 space or space that fits the next item.
    if post_residual == 0 {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
