    }

    // New Bin Logic:
    // Only open a new bin if the current bin_residual is significantly suboptimal for the item.
    // We penalize the 'New Bin' candidate (bin_residual == bin_capacity) 
    // unless the mean_residual is already very low, indicating that existing bins are nearly full.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 60.0;
        } else {
            score += 40.0;
        }
    }

    // Progression scaling: As we approach the end of the stream, 
    // be more aggressive about filling existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
