pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Best Fit Decreasing logic: We want the smallest post_residual (Best Fit).
    // However, we penalize tiny residuals that become "dead space" (e.g., < 10) 
    // unless we are near the end of the stream.
    let is_new_bin = bin_residual == bin_capacity;

    // Core objective: Minimize post_residual.
    let mut score = post * post;

    // Penalty for creating a new bin:
    // We increase the cost of opening a new bin as the stream progresses,
    // forcing the algorithm to be more aggressive about packing into existing bins.
    if is_new_bin {
        score += (bin_capacity as f64).powi(2) * (1.0 + progress);

        // If we have many open bins, opening another one is expensive.
        score += (open_bins_count as f64) * 50.0;
    } else {
        // Reward packing into bins that are already "tight" to keep them tight.
        // We look at the relationship between current post_residual and the mean_residual.
        if (post as f64) > mean_residual {
            score += (post - mean_residual).powi(2);
        }

        // Lookahead heuristic: If the next item is large, avoid leaving a bin 
        // with a residual smaller than the next item if possible.
        if next_item_size > 0 && post < (next_item_size as f64) && post > 0.0 {
            score += (next_item_size as f64 - post).powi(2) * 0.5;
        }
    }

    // If this is the only bin that fits the item (fitting_bins_count == 1),
    // we should prioritize it highly to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= (bin_capacity as f64).powi(2) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
