    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have fitting options
            score += 45.0 + (progress * 20.0);
        } else {
            // If no other option, normalize the cost
            score -= 10.0;
        }
    }

    // 4. Global state balancing:
    // If the mean residual of open bins is high, prefer bins that bring the current 
    // bin's residual closer to the global mean to maintain bin density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Dynamic scaling: Encourage tighter packing as we reach the end of the stream
    if progress > 0.8 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin heavily early in the stream, 
    // but allow it if the fit is exceptionally poor later.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 150.0 + (open_bins_count as f64 * 5.0)
    } else {
        0.0
    };

    // Objective: Minimize post_residual, but prioritize filling bins that are 
    // already "tight" to avoid fragmenting remaining space.
    // We use a quadratic penalty on the post_residual to favor Best-Fit behavior.
    let mut score = post.powf(1.5);

    // Lookahead logic: If the next item is large, favor bins that leave 
    // enough space for it (or minimize waste if it won't fit anyway).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for stranding the next item
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Reward for keeping space for the next item
            score -= (next_item_size as f64 * 0.5);
        }
    }

    // Interaction with mean_residual: If this bin's post_residual is significantly 
    // lower than the mean, it's a good fit.
    if !is_new_bin {
        score += (post - mean_residual) * 2.0;
    }

    // If this is the last fitting bin, prioritize it to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large residual space (waste).
    // We favor bins that result in smaller post_residual.
    score += (post_residual as f64).powf(1.2);

    // 2. Harmonic Class Logic: Reward placements that leave a residual 
    // that is a multiple of common item sizes or fits future expectations.
    // Specifically, penalize residuals that are "awkward" (e.g., < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; 
    }

    // 3. Lookahead Synergy: If the next item fits into the current post_residual,
    // heavily reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Thresholding: If we are forced to open a new bin (fitting_bins_count == 0),
    // normalize the cost of a new bin relative to the current average efficiency.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin, scaled by current density
        score = 60.0 + (mean_residual * 0.5);
    } else {
        // 5. Density Balancing: If we have many open bins, penalize residuals
        // that deviate significantly from the mean_residual to prevent fragmentation.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 6. Final progression bias: As we approach the end of the stream, 
    // favor tighter packing more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + (progress * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
