    // 6. Global efficiency: If this bin's residual is way above average, it's a "wasteful" bin, penalize it
    if (bin_residual as f64) > mean_residual * 1.5 {
        score += 15.0;
    }

    // 7. Last chance heuristic: If this is the only bin that fits the item, make it very attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 8. Progression scaling: As we approach the end of the stream, prioritize tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize near-empty bins
    // to encourage packing tightly (Best-Fit principle).
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead Synergy: If the next item fits into the post-placement residual, 
    // prioritize this bin to maximize bin utilization.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (1.0 - progress);
    }

    // 3. Last Chance Protection: If this is the only bin that can fit the current item, 
    // prioritize it strongly to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 4. Global Density Awareness: If current bins are mostly empty, try to fill them 
    // rather than opening new ones. If bins are tight, be more aggressive with new bins.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with how many bins are already open 
        // and how much room is available in existing bins.
        score += 35.0 + (open_bins_count as f64 * 0.5) + (mean_residual * 0.2);
    } else {
        // Reward filling existing bins that are already partially occupied.
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 5. End-of-Stream Phase: Become more conservative to avoid stranding items 
    // in the final stages.
    if progress > 0.95 {
        score -= (post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base score is the post-placement residual. 
    // We want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it is often worse than 0 (perfect fit).
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item can fit in the current post_residual, 
    // reward this bin heavily.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= (next_item_size as f64) * 1.5;
    }

    // Dynamic thresholding: as we progress through the stream, 
    // we become more conservative about opening new bins.
    // If this is a new bin (residual == capacity), penalize it based on progress.
    if bin_residual == bin_capacity {
        // Late in the stream, opening a new bin is very expensive.
        score += 15.0 + (progress * 40.0);

        // If we have many open bins that can fit the current item, 
        // opening a new one is likely wasteful.
        score += (fitting_bins_count as f64) * 10.0;
    } else {
        // If we are placing in an existing bin, reward bins that are 
        // closer to the mean residual (maintaining bin balance).
        let deviation = (residual - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // Non-linear coupling: penalize very small residuals that are unlikely 
    // to fit future items, especially if the bin is already quite full.
    if post > 0.0 && post < 8.0 {
        score += (8.0 - post).powf(1.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

