        // Base penalty for opening a new bin
        score += 30.0;
        // Increase penalty based on how far through the stream we are
        score += 20.0 * (step_index as f64 / total_items as f64);
        // Penalty for having too many open bins already
        score += open_bins_count as f64 * 2.0;
    }

    // 5. Mean Deviation: Favor bins that stay close to the current average utilization
    // to maintain uniformity across bins (Best-Fit style behavior).
    let current_utilization = bin_capacity - post_residual;
    let mean_utilization = bin_capacity as f64 - mean_residual;
    score += (current_utilization as f64 - mean_utilization).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We favor smaller post_residuals (classic Best-Fit).

    // 2. Lookahead Synergy: If the next item fits perfectly into the remaining space, 
    // heavily reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        // Reward configurations where the next item fits snugly.
        score -= (100.0 - diff) * 0.5;
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), penalize it based on how many
    // fitting bins exist. If many bins fit, opening a new one is inefficient.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 40.0;
        // Also penalize new bins as the stream progresses to consolidate late items.
        score += (step_index as f64 / total_items as f64) * 20.0;
    } else {
        // 4. Fragmentation Avoidance:
        // If post_residual is small but not zero, it creates "dead space".
        // Penalize residuals that are too small to fit common items (e.g., < 10).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }

        // 5. Mean-Residual Balancing:
        // If this bin's post_residual is significantly better (lower) than the current 
        // average, prioritize it to keep the global average residual low.
        if (post_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // 6. Last-Chance Logic:
    // If this is the only bin that fits the current item, prioritize it heavily
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize smaller post_residuals (which are good) 
    // to favor tightest fit, but avoid creating "dead zones" (1-9 range).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Lookahead Integration: If next_item_size fits in the post_residual, 
    // heavily reward this bin to favor packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Global State Awareness: If we are late in the stream, prioritize 
    // clearing out bins with low residuals to avoid fragmented endings.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (bin_capacity - bin_residual) as f64 * 0.5;
    }

    // 4. New Bin Thresholding: Discourage opening a new bin unless the 
    // current fit is extremely inefficient (e.g., post_residual is very large).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high.
        score = 85.0;

        // Dynamically lower the cost to open a new bin if we have many bins
        // already open, to prevent excessive fragmentation.
        if open_bins_count > 5 {
            score -= (open_bins_count as f64) * 2.0;
        }
    } else {
        // Penalty for using an existing bin that leaves a "bad" residual space
        // compared to the mean of other open bins.
        if (post_residual as f64) > mean_residual {
            score += 5.0;
        }

        // If this is the only bin that can fit the item, prioritize it.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: punish large post-residuals (Best Fit logic)
    let mut score = post_res;

    // Penalty for creating a "dead zone" (very small residual that cannot fit any likely item)
    // We define a dead zone threshold based on minimum item size (10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead interaction: if next_item_size is large, favor larger post_residual
    if next_item_size > 0 {
        let diff = (next_item_size as f64 - post_res).abs();
        score += 0.5 * diff;
    }

    // Dynamic thresholding: as we progress through the stream, become more conservative
    // about opening new bins. If this is a new bin (bin_residual == bin_capacity), 
    // penalize opening it based on progress.
    if bin_residual == bin_capacity {
        // High progress means we are nearing the end, so opening a new bin is expensive.
        score += 30.0 * (1.0 + progress);

        // If there are other bins that could fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Coupling with mean_residual: avoid bins that are significantly "emptier" than the average,
    // as they are likely suboptimal for packing density.
    if (bin_residual as f64) > mean_residual {
        score += 0.2 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // The core objective is to minimize post_residual (Best Fit),
    // but modified by harmonic considerations and lookahead pressure.

    let mut score = post_residual as f64;

    // 1. Harmonic Reward: Favor bins that leave a residual which is a multiple of 
    // common item sizes (e.g., 20, 25, 50) to minimize fragmentation.
    let harmonic_penalty = if post_residual > 0 {
        ((post_residual % 20) as f64) * 0.5 + ((post_residual % 25) as f64) * 0.3
    } else {
        -5.0 // Strong reward for perfect fit
    };
    score += harmonic_penalty;

    // 2. Lookahead Coupling: If the next item is large, avoid bins that would leave 
    // a tiny, unusable sliver (1-9) that prevents the next item from fitting.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize slivers that are too small to house the next item
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 3. New Bin Thresholding: If this is a new bin (bin_residual == bin_capacity),
    // only choose it if the current bin occupancy is inefficient or we are nearing end-of-stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Penalize opening a new bin early.
        score += 25.0 * (1.0 - progress);

        // If we have many fitting bins, opening a new one is highly discouraged.
        score += (fitting_bins_count as f64) * 10.0;
    }

    // 4. Mean Residual Balancing: Prevent extreme variance in bin fullness.
    // If this bin's post_residual is significantly better than the mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Best-Fit Decreasing logic modified by lookahead and dead-space avoidance.
    // 1. Penalize creation of "unusable gaps" (residual space < 10, as min item size is 10).
    // 2. Favor bins that maintain high packing density (low post_residual).
    // 3. Pressure against opening new bins unless the current fit is extremely poor.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (space too small for any future item)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead influence: if next_item_size is large, prefer leaving space for it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // New bin penalty: scale by current open_bins_count to prevent fragmentation
    if is_new_bin {
        // Only open a new bin if the fit is truly bad in existing bins
        // We set a high threshold so that existing bins are preferred unless they are all poor fits
        score += 40.0 + (open_bins_count as f64 * 2.0);
    } else {
        // Incentivize filling up existing bins to keep open_bins_count low
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // If this is the only bin that fits the item, highly prioritize it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post-residuals to keep bins tightly packed.
    // We normalize by capacity to ensure scale invariance.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // 2. Lookahead Synergy: If post_residual perfectly accommodates the next item, 
    // significantly reduce the score to prioritize this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64 / bin_capacity as f64) * 50.0;

        // Bonus for "exact fit" potential (minimizing wasted space)
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // 3. Last Chance Logic: If this is the only bin that can fit the item, 
    // we should prioritize it to avoid forcing a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 4. Global State Optimization: If we are creating a new bin, penalize based on 
    // how well the current items are packed. If mean_residual is already high, 
    // we want to avoid opening new bins unless necessary.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.5;
        // Penalize opening a new bin if we have many empty/partially filled bins
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Progression Weighting: As the stream nears completion, become more aggressive
    // about filling existing space (Best-Fit) rather than preserving space for future items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
