    if is_new_bin {
        score += 45.0 + (progress * 20.0);
    }

    // Heuristic: If we have very few bins left, be more aggressive with packing
    // If we have many bins, be more conservative (avoid creating "dead" space)
    if post_residual > 0 && post_residual < 10 {
