        }
    }

    // Global state coupling: Encourage filling bins that are already "near-empty"
    // to keep the number of active open bins low.
    if !is_new_bin {
        let residual_ratio = bin_residual as f64 / bin_capacity as f64;
        score -= (1.0 - residual_ratio) * 10.0;
    }

    // If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
