    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Archetype: Aggressive 2-step lookahead matching.

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    if is_new_bin {
        // Penalize opening a new bin heavily, but scale it down as the stream progresses
        // to avoid "bin-starvation" at the end.
        let progress = step_index as f64 / total_items as f64;
        score += 150.0 * (1.0 - progress);
    } else {
        // Strategy: Best-Fit variant with lookahead.

        // 1. Encourage tight fits (Best Fit property).
        // post_residual is already part of the base score.

        // 2. Lookahead matching: If the next item fits into the post_residual, 
        // we reward this placement significantly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (next_item_size as f64) * 0.8;

            // Further reward if this creates a "perfect" bin (residual 0).
            if post_residual == next_item_size {
                score -= 20.0;
            }
        }

        // 3. Penalty for creating "dead space":
        // If the residual is too small for any likely future item (e.g., < 10),
        // it effectively becomes wasted space.
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }

        // 4. Balance with mean_residual:
        // Avoid deviating too far from the average state of bins.
        score += (post_residual as f64 - mean_residual).abs() * 0.1;

        // 5. Urgency: If this is the last bin that can fit the item, 
        // prioritize it to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}
